/* ============================================================
   Silverpine Wilds — interface
   ============================================================ */

:root {
  --ink: #08110d;
  --ink-soft: #0e1b15;
  --pine: #14342a;
  --moss: #6f9b72;
  --fern: #9fc89a;
  --cream: #f4efe1;
  --cream-dim: #cfc9b8;
  --amber: #f2b45f;
  --amber-bright: #ffd18c;
  --amber-deep: #c98535;
  --danger: #f6c37b;
  --glass: rgba(9, 20, 15, 0.78);
  --line: rgba(244, 239, 225, 0.16);
  --line-strong: rgba(244, 239, 225, 0.28);
  --shadow: 0 32px 90px rgba(0, 0, 0, 0.55);
  --serif: "Palatino Linotype", "Book Antiqua", Palatino, "Iowan Old Style", Georgia, serif;
  --sans: "Avenir Next", "Segoe UI", Inter, system-ui, -apple-system, sans-serif;
  --safe-top: env(safe-area-inset-top, 0px);
  --safe-bottom: env(safe-area-inset-bottom, 0px);
  --safe-left: env(safe-area-inset-left, 0px);
  --safe-right: env(safe-area-inset-right, 0px);
}

* { box-sizing: border-box; }

html, body {
  height: 100%;
  margin: 0;
  overflow: hidden;
  background: var(--ink);
  color: var(--cream);
  font-family: var(--sans);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  overscroll-behavior: none;
}

body {
  position: fixed;
  inset: 0;
  touch-action: none;
  -webkit-user-select: none;
  user-select: none;
}

button, input, select { font: inherit; }
button { color: inherit; }
::selection { background: var(--amber); color: #1a1207; }

#scene {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  outline: none;
  cursor: crosshair;
}

.grain {
  position: absolute;
  inset: -20%;
  z-index: 1;
  pointer-events: none;
  opacity: 0.055;
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='180' height='180'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='0.72' numOctaves='3' stitchTiles='stitch'/><feColorMatrix type='saturate' values='0'/></filter><rect width='100%25' height='100%25' filter='url(%23n)' opacity='0.8'/></svg>");
  mix-blend-mode: soft-light;
  animation: grain-shift 1.2s steps(2) infinite;
}
@keyframes grain-shift {
  0% { transform: translate3d(0, 0, 0); }
  25% { transform: translate3d(-2%, 1%, 0); }
  50% { transform: translate3d(1%, -2%, 0); }
  75% { transform: translate3d(-1%, 2%, 0); }
  100% { transform: translate3d(0, 0, 0); }
}

.vignette {
  position: absolute;
  inset: 0;
  z-index: 2;
  pointer-events: none;
  background:
    radial-gradient(ellipse at 50% 45%, transparent 38%, rgba(4, 10, 7, 0.34) 100%),
    linear-gradient(to bottom, rgba(4, 10, 7, 0.28), transparent 18%, transparent 72%, rgba(4, 10, 7, 0.48));
}

/* ---------- shared type ---------- */

.eyebrow {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  margin: 0 0 1rem;
  font-size: 0.66rem;
  font-weight: 650;
  letter-spacing: 0.24em;
  text-transform: uppercase;
  color: var(--amber);
}
.eyebrow-line {
  display: inline-block;
  width: 34px;
  height: 1px;
  background: currentColor;
  opacity: 0.7;
}

kbd {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 1.55em;
  height: 1.55em;
  padding: 0 0.4em;
  margin: 0 0.12em;
  border-radius: 5px;
  border: 1px solid rgba(244, 239, 225, 0.3);
  border-bottom-color: rgba(244, 239, 225, 0.46);
  background: rgba(244, 239, 225, 0.08);
  color: var(--cream);
  font-family: var(--sans);
  font-size: 0.78em;
  font-weight: 650;
  line-height: 1;
  vertical-align: 0.06em;
  box-shadow: 0 1px 0 rgba(0, 0, 0, 0.35);
}

.is-hidden { display: none !important; }

/* ---------- loading ---------- */

.loading-screen {
  position: fixed;
  inset: 0;
  z-index: 200;
  display: grid;
  place-content: center;
  justify-items: center;
  gap: 0.4rem;
  background:
    radial-gradient(circle at 50% 44%, #17352a 0%, #08110d 68%);
  transition: opacity 0.8s ease, visibility 0.8s;
}
.loading-screen.done { opacity: 0; visibility: hidden; }
.loading-mark { display: flex; align-items: flex-end; gap: 5px; height: 42px; margin-bottom: 1.4rem; }
.loading-mark span {
  width: 5px;
  border-radius: 4px 4px 0 0;
  background: linear-gradient(to top, var(--amber-deep), var(--amber-bright));
  animation: grow 1.25s ease-in-out infinite alternate;
  transform-origin: bottom;
  height: 20px;
}
.loading-mark span:nth-child(1) { animation-delay: -0.2s; height: 28px; }
.loading-mark span:nth-child(2) { animation-delay: -0.4s; height: 40px; }
.loading-mark span:nth-child(3) { animation-delay: -0.6s; height: 24px; }
@keyframes grow { from { transform: scaleY(0.55); opacity: 0.55; } to { transform: scaleY(1); opacity: 1; } }
.loading-label {
  margin: 0;
  font-family: var(--serif);
  font-size: clamp(1.3rem, 2.2vw, 1.7rem);
  letter-spacing: 0.02em;
  color: var(--cream);
}
.loading-note {
  margin: 0;
  font-size: 0.7rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--cream-dim);
  opacity: 0.7;
}

/* ---------- buttons ---------- */

.btn {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.7rem;
  border: 1px solid transparent;
  border-radius: 999px;
  padding: 0.85rem 1.5rem;
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.13em;
  text-transform: uppercase;
  cursor: pointer;
  transition: transform 0.2s ease, background 0.2s ease, border-color 0.2s ease, color 0.2s ease, box-shadow 0.2s ease;
  -webkit-tap-highlight-color: transparent;
}
.btn svg { width: 1.05rem; height: 1.05rem; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
.btn:active { transform: translateY(1px) scale(0.99); }
.btn:focus-visible, .icon-button:focus-visible, .switch:focus-visible, .wide-button:focus-visible, .jump-button:focus-visible {
  outline: 2px solid var(--amber-bright);
  outline-offset: 3px;
}

.btn-primary {
  color: #1d1407;
  background: linear-gradient(180deg, var(--amber-bright), var(--amber));
  border-color: rgba(255, 237, 204, 0.65);
  box-shadow: 0 10px 28px rgba(216, 145, 49, 0.24), inset 0 1px 0 rgba(255, 255, 255, 0.45);
}
.btn-primary:hover { background: linear-gradient(180deg, #ffe0aa, var(--amber-bright)); box-shadow: 0 14px 34px rgba(216, 145, 49, 0.34); transform: translateY(-1px); }
.btn-large { padding: 1.05rem 1.9rem; font-size: 0.83rem; }

.btn-ghost {
  border-color: var(--line-strong);
  background: rgba(244, 239, 225, 0.05);
  color: var(--cream);
}
.btn-ghost:hover { border-color: rgba(244, 239, 225, 0.5); background: rgba(244, 239, 225, 0.1); }

.btn-ghost-light {
  border-color: rgba(244, 239, 225, 0.25);
  background: transparent;
  color: var(--cream);
}
.btn-ghost-light:hover { border-color: rgba(244, 239, 225, 0.55); background: rgba(244, 239, 225, 0.06); }

.icon-button {
  display: inline-grid;
  place-items: center;
  width: 42px;
  height: 42px;
  border-radius: 50%;
  border: 1px solid var(--line-strong);
  background: rgba(8, 17, 13, 0.42);
  color: var(--cream);
  cursor: pointer;
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  transition: background 0.2s ease, border-color 0.2s ease, transform 0.2s ease;
  -webkit-tap-highlight-color: transparent;
}
.icon-button:hover { background: rgba(244, 239, 225, 0.12); border-color: rgba(244, 239, 225, 0.45); transform: rotate(12deg); }
.icon-button svg { width: 19px; height: 19px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }

/* ---------- start screen ---------- */

.start-screen {
  position: absolute;
  inset: 0;
  z-index: 15;
  display: flex;
  align-items: flex-end;
  padding: calc(6vh + var(--safe-top)) clamp(1.4rem, 7vw, 7.5rem) calc(8vh + var(--safe-bottom));
  opacity: 1;
  transition: opacity 1s ease, visibility 1s;
}
.start-screen.fade-out { opacity: 0; visibility: hidden; pointer-events: none; }
.start-scrim {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(90deg, rgba(4, 12, 8, 0.9) 0%, rgba(4, 12, 8, 0.66) 32%, rgba(4, 12, 8, 0.1) 66%, transparent 100%),
    linear-gradient(0deg, rgba(4, 12, 8, 0.82) 0%, transparent 52%),
    radial-gradient(ellipse at 22% 58%, rgba(3, 10, 6, 0.55), transparent 58%);
  pointer-events: none;
}
.start-content {
  position: relative;
  width: min(620px, 92vw);
  text-shadow: 0 2px 30px rgba(0, 0, 0, 0.3);
  animation: rise-in 1.1s 0.15s both cubic-bezier(0.16, 1, 0.3, 1);
}
@keyframes rise-in {
  from { opacity: 0; transform: translateY(26px); }
  to { opacity: 1; transform: translateY(0); }
}
.game-title {
  margin: 0 0 0.9rem;
  font-family: var(--serif);
  font-size: clamp(4.2rem, 11.5vw, 9.4rem);
  font-weight: 400;
  line-height: 0.8;
  letter-spacing: -0.055em;
  color: var(--cream);
  text-transform: uppercase;
}
.game-title em {
  font-style: italic;
  font-weight: 400;
  text-transform: none;
  letter-spacing: -0.045em;
  color: var(--amber-bright);
  margin-left: 0.04em;
}
.tagline {
  margin: 1.7rem 0 2rem;
  max-width: 30rem;
  color: rgba(244, 239, 225, 0.82);
  font-size: clamp(0.9rem, 1.45vw, 1.02rem);
  line-height: 1.75;
  letter-spacing: 0.015em;
}
.start-actions { display: flex; align-items: center; flex-wrap: wrap; gap: 0.8rem; }
.start-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 1.6rem 2.8rem;
  margin-top: 2.6rem;
  padding-top: 1.5rem;
  border-top: 1px solid var(--line);
  max-width: 32rem;
}
.meta-block { min-width: 11rem; }
.meta-label {
  display: block;
  margin-bottom: 0.45rem;
  color: var(--amber);
  font-size: 0.58rem;
  font-weight: 700;
  letter-spacing: 0.2em;
  text-transform: uppercase;
}
.meta-block p { margin: 0; font-size: 0.76rem; line-height: 1.9; color: rgba(244, 239, 225, 0.68); }
.start-footnote {
  margin: 1.9rem 0 0;
  font-size: 0.64rem;
  letter-spacing: 0.08em;
  color: rgba(244, 239, 225, 0.45);
}
.start-corner {
  position: absolute;
  right: clamp(1.4rem, 5vw, 4rem);
  bottom: calc(8vh + var(--safe-bottom));
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 0.35rem;
  font-size: 0.58rem;
  letter-spacing: 0.18em;
  color: rgba(244, 239, 225, 0.4);
  text-transform: uppercase;
}

/* ---------- HUD ---------- */

.hud { position: absolute; inset: 0; z-index: 10; pointer-events: none; }
.hud.is-hidden { display: none !important; }

.topbar {
  position: absolute;
  top: calc(1.2rem + var(--safe-top));
  left: clamp(1rem, 2.5vw, 2rem);
  right: clamp(1rem, 2.5vw, 2rem);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
}
.wordmark {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  font-size: 0.64rem;
  font-weight: 700;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: rgba(244, 239, 225, 0.78);
  text-shadow: 0 1px 10px rgba(0, 0, 0, 0.5);
}
.wordmark-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--amber);
  box-shadow: 0 0 0 4px rgba(242, 180, 95, 0.13);
}

.compass {
  position: absolute;
  left: 50%;
  top: -0.2rem;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.16rem;
}
.compass-window {
  position: relative;
  width: 192px;
  height: 30px;
  overflow: hidden;
  border-radius: 999px;
  border: 1px solid rgba(244, 239, 225, 0.16);
  background: rgba(8, 17, 13, 0.45);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  mask-image: linear-gradient(90deg, transparent, #000 18%, #000 82%, transparent);
  -webkit-mask-image: linear-gradient(90deg, transparent, #000 18%, #000 82%, transparent);
}
.compass-track { position: absolute; top: 7px; left: 0; height: 16px; white-space: nowrap; will-change: transform; }
.compass-tick {
  position: absolute;
  bottom: 0;
  width: 1px;
  height: 4px;
  background: rgba(244, 239, 225, 0.28);
}
.compass-tick.major { height: 8px; background: rgba(244, 239, 225, 0.55); }
.compass-label {
  position: absolute;
  top: -2px;
  transform: translateX(-50%);
  font-size: 0.5rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: rgba(244, 239, 225, 0.72);
}
.compass-label.cardinal { color: var(--amber-bright); font-size: 0.56rem; }
.compass-pointer {
  position: absolute;
  bottom: -3px;
  left: 50%;
  width: 0;
  height: 0;
  transform: translateX(-50%);
  border-left: 3px solid transparent;
  border-right: 3px solid transparent;
  border-bottom: 5px solid var(--amber);
}
.compass-readout {
  font-size: 0.55rem;
  font-weight: 700;
  letter-spacing: 0.2em;
  color: rgba(244, 239, 225, 0.66);
  text-shadow: 0 1px 6px rgba(0, 0, 0, 0.6);
}

.topbar-actions { display: flex; align-items: center; gap: 0.6rem; pointer-events: auto; }
.potato-pill {
  padding: 0.35rem 0.68rem;
  border: 1px solid rgba(242, 180, 95, 0.45);
  border-radius: 999px;
  background: rgba(59, 39, 12, 0.4);
  color: var(--amber-bright);
  font-size: 0.52rem;
  font-weight: 800;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  backdrop-filter: blur(10px);
}

.crosshair {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 16px;
  height: 16px;
  transform: translate(-50%, -50%);
  opacity: 0.5;
  transition: opacity 0.3s ease, transform 0.3s ease;
}
.crosshair span { position: absolute; background: rgba(244, 239, 225, 0.9); box-shadow: 0 0 4px rgba(0, 0, 0, 0.7); }
.crosshair span:nth-child(1) { left: 50%; top: 0; width: 1px; height: 5px; transform: translateX(-50%); }
.crosshair span:nth-child(2) { left: 0; top: 50%; width: 5px; height: 1px; transform: translateY(-50%); }
body.is-looking .crosshair { opacity: 0.85; transform: translate(-50%, -50%) scale(1.15); }

.hud-footer {
  position: absolute;
  left: clamp(1rem, 2.5vw, 2rem);
  right: clamp(1rem, 2.5vw, 2rem);
  bottom: calc(1.2rem + var(--safe-bottom));
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  font-size: 0.58rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: rgba(244, 239, 225, 0.58);
}
.location-chip {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.42rem 0.75rem;
  border-radius: 999px;
  border: 1px solid rgba(244, 239, 225, 0.13);
  background: rgba(8, 17, 13, 0.38);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  color: rgba(244, 239, 225, 0.8);
}
.location-pulse {
  width: 5px; height: 5px; border-radius: 50%;
  background: var(--fern);
  box-shadow: 0 0 0 3px rgba(159, 200, 154, 0.12);
  animation: pulse 2.8s ease-in-out infinite;
}
@keyframes pulse { 0%,100% { opacity: 0.5; } 50% { opacity: 1; } }
.desktop-hint { display: flex; align-items: center; gap: 0.65rem; }
.desktop-hint span { display: inline-flex; align-items: center; gap: 0.35rem; white-space: nowrap; }
.desktop-hint i, .walk-stats i { width: 2px; height: 2px; border-radius: 50%; background: rgba(244, 239, 225, 0.35); }
.desktop-hint kbd { min-width: 1.35em; height: 1.35em; font-size: 0.78em; opacity: 0.75; }
.walk-stats { display: flex; align-items: center; gap: 0.55rem; font-variant-numeric: tabular-nums; white-space: nowrap; }
#walkTime { color: rgba(244, 239, 225, 0.82); }

/* ---------- mobile controls ---------- */

.mobile-controls { position: absolute; inset: 0; z-index: 20; pointer-events: none; }
.mobile-controls.is-hidden { display: none !important; }
.joystick {
  position: absolute;
  left: calc(1.15rem + var(--safe-left));
  bottom: calc(1.4rem + var(--safe-bottom));
  width: 132px;
  height: 132px;
  border-radius: 50%;
  pointer-events: auto;
  touch-action: none;
  background: radial-gradient(circle at 50% 45%, rgba(15, 33, 25, 0.4), rgba(5, 12, 8, 0.34));
  border: 1px solid rgba(244, 239, 225, 0.16);
  box-shadow: inset 0 0 36px rgba(0, 0, 0, 0.28);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
}
.joystick-ring {
  position: absolute;
  inset: 18px;
  border-radius: 50%;
  border: 1px dashed rgba(244, 239, 225, 0.18);
}
.joystick-arrows {
  position: absolute;
  inset: 0;
  font-size: 0.5rem;
  color: rgba(244, 239, 225, 0.34);
}
.joystick-arrows span { position: absolute; left: 50%; top: 50%; }
.joystick-arrows span:nth-child(1) { transform: translate(-50%, -58px); }
.joystick-arrows span:nth-child(2) { transform: translate(-50%, 50px); }
.joystick-arrows span:nth-child(3) { transform: translate(-58px, -50%); }
.joystick-arrows span:nth-child(4) { transform: translate(52px, -50%); }
.joystick-knob {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 56px;
  height: 56px;
  border-radius: 50%;
  transform: translate(-50%, -50%);
  background: radial-gradient(circle at 36% 30%, rgba(255, 234, 198, 0.3), rgba(124, 153, 122, 0.28) 42%, rgba(16, 36, 27, 0.7));
  border: 1px solid rgba(244, 239, 225, 0.4);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.35), inset 0 1px 1px rgba(255, 255, 255, 0.2);
  transition: transform 0.08s linear;
  will-change: transform;
}
.joystick.active .joystick-knob { transition: none; background: radial-gradient(circle at 36% 30%, rgba(255, 234, 198, 0.45), rgba(124, 153, 122, 0.4) 42%, rgba(16, 36, 27, 0.8)); }
.jump-button {
  position: absolute;
  right: calc(1.25rem + var(--safe-right));
  bottom: calc(1.7rem + var(--safe-bottom));
  width: 94px;
  height: 94px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0.22rem;
  border-radius: 50%;
  border: 1px solid rgba(244, 239, 225, 0.35);
  background: radial-gradient(circle at 40% 30%, rgba(255, 224, 172, 0.3), rgba(33, 58, 42, 0.6));
  color: var(--cream);
  pointer-events: auto;
  touch-action: none;
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.3), inset 0 1px 1px rgba(255, 255, 255, 0.22);
  transition: transform 0.1s ease, background 0.1s ease;
  -webkit-tap-highlight-color: transparent;
}
.jump-button svg { width: 24px; height: 24px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
.jump-button span { font-size: 0.52rem; font-weight: 800; letter-spacing: 0.17em; text-transform: uppercase; opacity: 0.78; }
.jump-button.pressed { transform: scale(0.93); background: radial-gradient(circle at 40% 30%, rgba(255, 224, 172, 0.55), rgba(66, 98, 67, 0.7)); }
.look-hint {
  position: absolute;
  left: 50%;
  bottom: calc(1.65rem + var(--safe-bottom));
  transform: translateX(-50%);
  padding: 0.36rem 0.75rem;
  border-radius: 999px;
  background: rgba(8, 17, 13, 0.36);
  border: 1px solid rgba(244, 239, 225, 0.1);
  color: rgba(244, 239, 225, 0.45);
  font-size: 0.52rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  white-space: nowrap;
  transition: opacity 1s ease;
  pointer-events: none;
}
.look-hint.fade { opacity: 0; }

/* ---------- modal shared ---------- */

.modal-layer {
  position: fixed;
  inset: 0;
  z-index: 60;
  display: grid;
  place-items: center;
  padding: calc(1.2rem + var(--safe-top)) 1.2rem calc(1.2rem + var(--safe-bottom));
  background: rgba(3, 9, 6, 0.58);
  backdrop-filter: blur(7px) saturate(0.9);
  -webkit-backdrop-filter: blur(7px) saturate(0.9);
  animation: fade-in 0.5s both ease;
}
@keyframes fade-in { from { opacity: 0; } to { opacity: 1; } }

.warning-card {
  position: relative;
  width: min(660px, 100%);
  max-height: calc(100dvh - 2.2rem);
  overflow-y: auto;
  padding: clamp(1.6rem, 4vw, 2.8rem);
  border-radius: 22px;
  border: 1px solid rgba(242, 180, 95, 0.4);
  background:
    linear-gradient(150deg, rgba(29, 45, 34, 0.96), rgba(8, 18, 13, 0.985) 60%),
    var(--ink);
  box-shadow: var(--shadow), 0 0 0 1px rgba(242, 180, 95, 0.07), 0 0 90px rgba(242, 180, 95, 0.09);
  animation: card-in 0.7s 0.1s both cubic-bezier(0.16, 1, 0.3, 1);
  scrollbar-width: thin;
  scrollbar-color: rgba(242, 180, 95, 0.35) transparent;
}
@keyframes card-in {
  from { opacity: 0; transform: translateY(18px) scale(0.985); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}
.warning-card::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  pointer-events: none;
  background: radial-gradient(ellipse at 90% 0%, rgba(242, 180, 95, 0.12), transparent 55%);
}
.warning-rule { display: flex; align-items: center; gap: 0.8rem; margin-bottom: 1.15rem; color: var(--amber); }
.warning-rule span { flex: 1; height: 1px; background: linear-gradient(90deg, transparent, rgba(242, 180, 95, 0.3)); }
.warning-rule span:last-child { background: linear-gradient(90deg, rgba(242, 180, 95, 0.3), transparent); }
.warning-rule em { font-style: normal; font-size: 0.58rem; font-weight: 800; letter-spacing: 0.28em; text-transform: uppercase; white-space: nowrap; }
.warning-card h2 {
  margin: 0 0 1.1rem;
  font-family: var(--serif);
  font-size: clamp(1.9rem, 4.4vw, 2.75rem);
  font-weight: 400;
  letter-spacing: -0.02em;
  line-height: 1.05;
}
.warning-copy {
  margin: 0 0 1.35rem;
  max-width: 39rem;
  font-size: clamp(0.9rem, 2.1vw, 1rem);
  line-height: 1.9;
  color: rgba(244, 239, 225, 0.78);
}
.hi {
  color: var(--cream);
  font-weight: 700;
  background: linear-gradient(180deg, transparent 58%, rgba(242, 180, 95, 0.22) 58%);
  padding: 0 0.06em;
  border-radius: 2px;
  box-decoration-break: clone;
  -webkit-box-decoration-break: clone;
}
.hi-warn { color: #ffd7a0; background: linear-gradient(180deg, transparent 56%, rgba(242, 122, 75, 0.3) 56%); }
.hi-good {
  color: #bde5b0;
  background: linear-gradient(180deg, transparent 56%, rgba(126, 194, 112, 0.26) 56%);
  text-decoration: underline;
  text-decoration-color: rgba(189, 229, 176, 0.45);
  text-underline-offset: 4px;
}
.warning-tip {
  display: flex;
  align-items: flex-start;
  gap: 0.7rem;
  margin: 0 0 1.7rem;
  padding: 0.8rem 0.95rem;
  border-radius: 11px;
  border: 1px solid rgba(244, 239, 225, 0.1);
  background: rgba(244, 239, 225, 0.045);
  color: rgba(244, 239, 225, 0.62);
  font-size: 0.74rem;
  line-height: 1.65;
}
.warning-tip svg { flex: 0 0 auto; width: 16px; height: 16px; margin-top: 0.1rem; fill: none; stroke: var(--amber); stroke-width: 1.6; stroke-linecap: round; }
.warning-actions { display: flex; flex-wrap: wrap; gap: 0.75rem; }
.warning-actions .btn { min-width: 8.5rem; }
.warning-small {
  margin: 1.15rem 0 0;
  font-size: 0.62rem;
  letter-spacing: 0.04em;
  color: rgba(244, 239, 225, 0.42);
  line-height: 1.6;
}

/* ---------- settings drawer ---------- */

.drawer-scrim {
  position: fixed;
  inset: 0;
  z-index: 70;
  background: rgba(3, 9, 6, 0.45);
  backdrop-filter: blur(3px);
  -webkit-backdrop-filter: blur(3px);
  animation: fade-in 0.3s both ease;
}
.settings-panel {
  position: fixed;
  z-index: 71;
  top: 0;
  right: 0;
  bottom: 0;
  width: min(440px, 100vw);
  overflow-y: auto;
  padding: calc(1.4rem + var(--safe-top)) clamp(1.2rem, 3vw, 1.8rem) calc(1.5rem + var(--safe-bottom));
  border-left: 1px solid rgba(244, 239, 225, 0.14);
  background:
    radial-gradient(ellipse at 100% 0%, rgba(54, 85, 60, 0.35), transparent 44%),
    rgba(8, 18, 13, 0.96);
  box-shadow: -30px 0 90px rgba(0, 0, 0, 0.45);
  backdrop-filter: blur(24px);
  -webkit-backdrop-filter: blur(24px);
  animation: drawer-in 0.38s cubic-bezier(0.16, 1, 0.3, 1) both;
  scrollbar-width: thin;
  scrollbar-color: rgba(244, 239, 225, 0.2) transparent;
}
@keyframes drawer-in { from { transform: translateX(100%); } to { transform: translateX(0); } }
.settings-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 1rem; margin-bottom: 1.5rem; }
.settings-head .eyebrow { margin-bottom: 0.55rem; }
.settings-head h2 { margin: 0; font-family: var(--serif); font-size: 2rem; font-weight: 400; letter-spacing: -0.02em; }
.settings-section { padding: 1.15rem 0; border-top: 1px solid var(--line); }
.settings-section-last { padding-bottom: 0; }
.section-title {
  margin: 0 0 0.95rem;
  color: rgba(244, 239, 225, 0.45);
  font-size: 0.58rem;
  font-weight: 800;
  letter-spacing: 0.22em;
  text-transform: uppercase;
}
.setting-row { display: flex; align-items: flex-start; justify-content: space-between; gap: 1rem; }
.setting-row-featured {
  padding: 0.95rem;
  margin: 0 -0.95rem;
  border-radius: 13px;
  border: 1px solid rgba(242, 180, 95, 0.22);
  background: linear-gradient(135deg, rgba(242, 180, 95, 0.09), rgba(242, 180, 95, 0.02));
}
.setting-copy { max-width: 19rem; }
.setting-label { display: block; font-size: 0.86rem; font-weight: 650; line-height: 1.4; }
.recommended {
  display: inline-block;
  margin-top: 0.25rem;
  color: var(--amber);
  font-size: 0.5rem;
  font-weight: 700;
  letter-spacing: 0.13em;
  text-transform: uppercase;
}
.setting-copy p { margin: 0.35rem 0 0; color: rgba(244, 239, 225, 0.5); font-size: 0.69rem; line-height: 1.65; }
.switch {
  flex: 0 0 auto;
  padding: 0;
  border: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}
.switch-track {
  position: relative;
  display: block;
  width: 48px;
  height: 28px;
  border-radius: 999px;
  background: rgba(244, 239, 225, 0.14);
  border: 1px solid rgba(244, 239, 225, 0.18);
  transition: background 0.25s ease, border-color 0.25s ease;
}
.switch-knob {
  position: absolute;
  top: 3px;
  left: 3px;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: rgba(244, 239, 225, 0.75);
  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.35);
  transition: transform 0.25s cubic-bezier(0.16, 1, 0.3, 1), background 0.25s ease;
}
.switch[aria-checked="true"] .switch-track { background: rgba(242, 180, 95, 0.32); border-color: rgba(242, 180, 95, 0.7); }
.switch[aria-checked="true"] .switch-knob { transform: translateX(20px); background: var(--amber-bright); }
.switch.pulse .switch-track { animation: switch-pulse 0.7s ease 2; }
@keyframes switch-pulse {
  0%, 100% { box-shadow: 0 0 0 0 rgba(242, 180, 95, 0); }
  50% { box-shadow: 0 0 0 6px rgba(242, 180, 95, 0.22); }
}

.range-row {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 0.35rem 1rem;
  margin: 0 0 1.15rem;
  font-size: 0.78rem;
  color: rgba(244, 239, 225, 0.82);
}
.range-row:last-of-type { margin-bottom: 0.6rem; }
.range-row output { color: var(--amber); font-size: 0.7rem; font-weight: 650; font-variant-numeric: tabular-nums; }
.range-row input[type="range"] { grid-column: 1 / -1; width: 100%; margin: 0.2rem 0 0; appearance: none; -webkit-appearance: none; height: 3px; border-radius: 99px; background: rgba(244, 239, 225, 0.18); outline: none; }
.range-row input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none;
  width: 15px; height: 15px; border-radius: 50%;
  background: var(--amber-bright); border: 2px solid #2a1d0a;
  box-shadow: 0 0 0 4px rgba(242, 180, 95, 0.13);
  cursor: pointer;
}
.range-row input[type="range"]::-moz-range-thumb { width: 14px; height: 14px; border: 2px solid #2a1d0a; border-radius: 50%; background: var(--amber-bright); cursor: pointer; }
.select-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  margin-top: 1rem;
  font-size: 0.78rem;
  color: rgba(244, 239, 225, 0.82);
}
.select-row select {
  max-width: 13rem;
  padding: 0.45rem 2rem 0.45rem 0.7rem;
  border-radius: 8px;
  border: 1px solid rgba(244, 239, 225, 0.18);
  background: rgba(244, 239, 225, 0.06);
  color: var(--cream);
  font-size: 0.7rem;
  appearance: none;
  -webkit-appearance: none;
  background-image: linear-gradient(45deg, transparent 50%, rgba(244,239,225,.6) 50%), linear-gradient(135deg, rgba(244,239,225,.6) 50%, transparent 50%);
  background-position: calc(100% - 14px) 52%, calc(100% - 9px) 52%;
  background-size: 5px 5px, 5px 5px;
  background-repeat: no-repeat;
  cursor: pointer;
}
.select-row select:focus-visible { outline: 2px solid var(--amber-bright); outline-offset: 2px; }
.select-row option { background: #0d1b14; color: var(--cream); }

.wide-button {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.6rem;
  width: 100%;
  padding: 0.8rem 1rem;
  border-radius: 10px;
  border: 1px solid rgba(244, 239, 225, 0.18);
  background: rgba(244, 239, 225, 0.05);
  color: var(--cream);
  font-size: 0.72rem;
  font-weight: 650;
  letter-spacing: 0.08em;
  cursor: pointer;
  transition: background 0.2s ease, border-color 0.2s ease;
}
.wide-button:hover { background: rgba(244, 239, 225, 0.1); border-color: rgba(244, 239, 225, 0.34); }
.wide-button svg { width: 15px; height: 15px; fill: none; stroke: var(--amber); stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
.settings-note { margin: 1rem 0 0; font-size: 0.62rem; line-height: 1.8; color: rgba(244, 239, 225, 0.42); }

/* ---------- pause ---------- */

.pause-layer { z-index: 80; }
.pause-card {
  width: min(480px, 100%);
  padding: clamp(1.7rem, 4vw, 2.6rem);
  border-radius: 20px;
  border: 1px solid var(--line-strong);
  background: linear-gradient(150deg, rgba(27, 46, 34, 0.97), rgba(8, 18, 13, 0.985));
  box-shadow: var(--shadow);
  animation: card-in 0.4s both cubic-bezier(0.16, 1, 0.3, 1);
  text-align: center;
}
.pause-card .eyebrow { justify-content: center; }
.pause-card h2 { margin: 0 0 0.6rem; font-family: var(--serif); font-size: clamp(1.8rem, 5vw, 2.4rem); font-weight: 400; }
.pause-copy { margin: 0 0 1.6rem; color: rgba(244, 239, 225, 0.55); font-size: 0.8rem; line-height: 1.7; }
.pause-actions { display: flex; justify-content: center; flex-wrap: wrap; gap: 0.7rem; }
.pause-tip { margin-top: 1.4rem; font-size: 0.62rem; letter-spacing: 0.05em; color: rgba(244, 239, 225, 0.4); }

/* ---------- toast / rotate ---------- */

.toast {
  position: fixed;
  z-index: 100;
  left: 50%;
  bottom: calc(2.2rem + var(--safe-bottom));
  transform: translate(-50%, 16px);
  max-width: calc(100vw - 2rem);
  padding: 0.72rem 1.1rem;
  border-radius: 999px;
  border: 1px solid rgba(242, 180, 95, 0.35);
  background: rgba(10, 22, 16, 0.92);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  box-shadow: 0 14px 40px rgba(0, 0, 0, 0.4);
  color: var(--cream);
  font-size: 0.7rem;
  letter-spacing: 0.04em;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.3s ease, transform 0.3s ease;
  text-align: center;
}
.toast.show { opacity: 1; transform: translate(-50%, 0); }
.toast strong { color: var(--amber-bright); }

.rotate-hint {
  position: fixed;
  z-index: 150;
  left: 50%;
  bottom: calc(1.2rem + var(--safe-bottom));
  transform: translateX(-50%);
  padding: 0.4rem 0.8rem;
  border-radius: 999px;
  border: 1px solid var(--line);
  background: rgba(8, 17, 13, 0.8);
  font-size: 0.55rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: rgba(244, 239, 225, 0.6);
  pointer-events: none;
}

/* ---------- responsive ---------- */

@media (max-width: 900px) {
  .compass-window { width: 150px; }
  .wordmark span:last-child { display: none; }
  .start-corner { display: none; }
  .desktop-hint { display: none; }
  .hud-footer { justify-content: space-between; }
  .walk-stats { margin-left: auto; }
}

@media (max-width: 640px) {
  .start-screen {
    align-items: center;
    padding: calc(10vh + var(--safe-top)) 1.25rem calc(9vh + var(--safe-bottom));
  }
  .start-scrim {
    background:
      linear-gradient(0deg, rgba(4, 12, 8, 0.94) 0%, rgba(4, 12, 8, 0.55) 50%, rgba(4, 12, 8, 0.2) 100%),
      radial-gradient(ellipse at 50% 55%, rgba(3, 10, 6, 0.35), transparent 70%);
  }
  .start-content { text-align: center; }
  .start-content .eyebrow { justify-content: center; }
  .game-title { font-size: clamp(3.6rem, 20vw, 5.6rem); }
  .tagline { margin: 1.35rem auto 1.7rem; font-size: 0.84rem; line-height: 1.65; }
  .start-actions { justify-content: center; }
  .start-meta { display: none; }
