/* Deterministic noise helpers shared by the forest modules. */

export function mulberry32(seed) {
  let a = seed >>> 0;
  return function random() {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export function hash2(x, y) {
  let h = Math.imul(x, 374761393) + Math.imul(y, 668265263);
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  return ((h ^ (h >>> 16)) >>> 0) / 4294967296;
}

export const clamp = (v, a, b) => Math.min(b, Math.max(a, v));
export const lerp = (a, b, t) => a + (b - a) * t;
export const smooth = (t) => t * t * (3 - 2 * t);

export function smoothstep(a, b, x) {
  const t = clamp((x - a) / (b - a), 0, 1);
  return t * t * (3 - 2 * t);
}

export function valueNoise(x, y) {
  const xi = Math.floor(x);
  const yi = Math.floor(y);
  const u = smooth(x - xi);
  const v = smooth(y - yi);
  const a = hash2(xi, yi);
  const b = hash2(xi + 1, yi);
  const c = hash2(xi, yi + 1);
  const d = hash2(xi + 1, yi + 1);
  return lerp(lerp(a, b, u), lerp(c, d, u), v);
}

export function fbm(x, y, octaves = 4, lacunarity = 2.03, gain = 0.5) {
  let amp = 0.5;
  let freq = 1;
  let sum = 0;
  let norm = 0;
  for (let i = 0; i < octaves; i++) {
    sum += amp * valueNoise(x * freq, y * freq);
    norm += amp;
    amp *= gain;
    freq *= lacunarity;
  }
  return sum / norm;
}

export function makeCanvas(size, height = size) {
  const canvas = document.createElement('canvas');
  canvas.width = size;
  canvas.height = height;
  return canvas;
}

import * as THREE from '../vendor/three.module.min.js';
import { mulberry32, makeCanvas } from './noise.js';

/* ---------- ground ---------- */

export function makeGroundMaps() {
  const rng = mulberry32(9417);
  const size = 512;
  const canvas = makeCanvas(size);
  const ctx = canvas.getContext('2d');
  ctx.fillStyle = '#c9c3ae';
  ctx.fillRect(0, 0, size, size);

  for (let i = 0; i < 90; i++) {
    const r = 8 + rng() * 46;
    ctx.fillStyle = rng() > 0.5
      ? `rgba(112, 101, 79, ${0.04 + rng() * 0.07})`
      : `rgba(226, 219, 196, ${0.04 + rng() * 0.06})`;
    ctx.beginPath();
    ctx.arc(rng() * size, rng() * size, r, 0, Math.PI * 2);
    ctx.fill();
  }

  // Soil grain
  for (let i = 0; i < 26000; i++) {
    const x = rng() * size;
    const y = rng() * size;
    const s = 0.4 + rng() * 1.5;
    const tone = rng();
    ctx.fillStyle = tone > 0.72
      ? `rgba(238, 231, 209, ${0.08 + rng() * 0.2})`
      : `rgba(74, 65, 49, ${0.05 + rng() * 0.23})`;
    ctx.fillRect(x, y, s, s * (0.6 + rng()));
  }

  // Twigs and pine needles
  for (let i = 0; i < 420; i++) {
    const x = rng() * size;
    const y = rng() * size;
    const a = rng() * Math.PI * 2;
    const len = 3 + rng() * 16;
    ctx.strokeStyle = rng() > 0.5
      ? `rgba(74, 58, 38, ${0.14 + rng() * 0.2})`
      : `rgba(174, 143, 86, ${0.1 + rng() * 0.17})`;
    ctx.lineWidth = 0.5 + rng();
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.lineTo(x + Math.cos(a) * len, y + Math.sin(a) * len);
    ctx.stroke();
  }

  // Tiny moss flecks
  for (let i = 0; i < 700; i++) {
    const x = rng() * size;
    const y = rng() * size;
    const r = 1 + rng() * 5;
    ctx.fillStyle = `rgba(${60 + rng() * 30}, ${74 + rng() * 35}, ${38 + rng() * 20}, ${0.05 + rng() * 0.12})`;
    ctx.beginPath();
    ctx.arc(x, y, r, 0, Math.PI * 2);
    ctx.fill();
  }

  const map = new THREE.CanvasTexture(canvas);
  map.wrapS = map.wrapT = THREE.RepeatWrapping;
  map.repeat.set(52, 52);
  map.colorSpace = THREE.SRGBColorSpace;
  map.anisotropy = 8;

  // A soft, grayscale height field for the bump map.
  const bumpCanvas = makeCanvas(256);
  const bctx = bumpCanvas.getContext('2d');
  const bimg = bctx.createImageData(256, 256);
  for (let i = 0; i < 256 * 256; i++) {
    const v = 108 + rng() * 70;
    bimg.data[i * 4] = v;
    bimg.data[i * 4 + 1] = v;
    bimg.data[i * 4 + 2] = v;
    bimg.data[i * 4 + 3] = 255;
  }
  bctx.putImageData(bimg, 0, 0);
  for (let i = 0; i < 2400; i++) {
    const x = rng() * 256;
    const y = rng() * 256;
    bctx.fillStyle = `rgba(40, 40, 40, ${0.08 + rng() * 0.25})`;
    bctx.fillRect(x, y, 1 + rng() * 2, 1 + rng() * 2);
  }
  const bump = new THREE.CanvasTexture(bumpCanvas);
  bump.wrapS = bump.wrapT = THREE.RepeatWrapping;
  bump.repeat.set(52, 52);

  return { map, bump };
}

/* ---------- trail ---------- */

export function makePathTexture() {
  const rng = mulberry32(7223);
  const size = 512;
  const canvas = makeCanvas(size);
  const ctx = canvas.getContext('2d');

  const grad = ctx.createLinearGradient(0, 0, size, 0);
  grad.addColorStop(0, 'rgba(112, 96, 68, 0)');
  grad.addColorStop(0.12, 'rgba(112, 96, 68, 0.72)');
  grad.addColorStop(0.24, 'rgba(122, 105, 76, 0.98)');
  grad.addColorStop(0.76, 'rgba(118, 101, 73, 0.98)');
  grad.addColorStop(0.88, 'rgba(112, 96, 68, 0.7)');
  grad.addColorStop(1, 'rgba(112, 96, 68, 0)');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, size, size);

  // Uneven, scuffed edges.
  ctx.globalCompositeOperation = 'destination-out';
  for (let y = 0; y < size; y += 3) {
    const left = 34 + Math.sin(y * 0.05) * 8 + rng() * 18;
    const right = 478 - Math.sin(y * 0.043 + 2) * 9 - rng() * 18;
    ctx.beginPath();
