  }
  ctx.globalCompositeOperation = 'source-over';

  // Dirt mottling.
  for (let i = 0; i < 5200; i++) {
    const x = 50 + rng() * 412;
    const y = rng() * size;
    const s = 0.7 + rng() * 3.4;
    const dark = rng() > 0.48;
    ctx.fillStyle = dark
      ? `rgba(${52 + rng() * 26}, ${43 + rng() * 22}, ${28 + rng() * 18}, ${0.08 + rng() * 0.24})`
