  // Small stones in the track.
  for (let i = 0; i < 260; i++) {
    const x = 80 + rng() * 352;
    const y = rng() * size;
    const r = 1.5 + rng() * 6;
    ctx.fillStyle = `rgba(${96 + rng() * 52}, ${92 + rng() * 45}, ${78 + rng() * 38}, ${0.22 + rng() * 0.42})`;
    ctx.beginPath();
    ctx.ellipse(x, y, r, r * 0.72, rng() * Math.PI, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = 'rgba(224, 215, 189, 0.2)';
    ctx.beginPath();
    ctx.ellipse(x - r * 0.2, y - r * 0.25, r * 0.52, r * 0.32, rng() * Math.PI, 0, Math.PI * 2);
    ctx.fill();
  }

  // Moss creeping in from the edges.
  for (let i = 0; i < 340; i++) {
    const side = rng() > 0.5;
    const x = side ? 30 + rng() * 52 : 430 + rng() * 55;
    const y = rng() * size;
    ctx.fillStyle = `rgba(${47 + rng() * 26}, ${67 + rng() * 28}, ${34 + rng() * 20}, ${0.1 + rng() * 0.2})`;
    ctx.beginPath();
    ctx.arc(x, y, 2 + rng() * 9, 0, Math.PI * 2);
    ctx.fill();
  }

  const map = new THREE.CanvasTexture(canvas);
  map.wrapS = THREE.ClampToEdgeWrapping;
  map.wrapT = THREE.RepeatWrapping;
  map.colorSpace = THREE.SRGBColorSpace;
  map.anisotropy = 8;
  return map;
}

/* ---------- bark ---------- */

export function makeBarkTexture() {
  const rng = mulberry32(3389);
  const w = 256;
  const h = 256;
  const canvas = makeCanvas(w, h);
  const ctx = canvas.getContext('2d');
  ctx.fillStyle = '#6a5b47';
  ctx.fillRect(0, 0, w, h);

  for (let i = 0; i < 130; i++) {
    const x = rng() * w;
    const width = 1 + rng() * 9;
    ctx.strokeStyle = rng() > 0.5
      ? `rgba(${42 + rng() * 24}, ${35 + rng() * 20}, ${24 + rng() * 16}, ${0.16 + rng() * 0.34})`
      : `rgba(${160 + rng() * 45}, ${144 + rng() * 36}, ${115 + rng() * 30}, ${0.08 + rng() * 0.22})`;
    ctx.lineWidth = width;
    ctx.beginPath();
    let y = -10;
    let cx = x;
    ctx.moveTo(cx, y);
    while (y < h + 10) {
      y += 8 + rng() * 15;
      cx += (rng() - 0.5) * 6;
      ctx.lineTo(cx, y);
    }
    ctx.stroke();
  }

  // Knots
  for (let i = 0; i < 22; i++) {
    const x = rng() * w;
    const y = rng() * h;
    const r = 2 + rng() * 8;
    ctx.strokeStyle = `rgba(40, 32, 22, ${0.25 + rng() * 0.3})`;
    ctx.lineWidth = 1 + rng() * 1.6;
    ctx.beginPath();
    ctx.ellipse(x, y, r, r * 0.45, 0, 0, Math.PI * 2);
    ctx.stroke();
    ctx.fillStyle = `rgba(42, 34, 23, ${0.18 + rng() * 0.2})`;
    ctx.beginPath();
    ctx.ellipse(x, y, r * 0.55, r * 0.24, 0, 0, Math.PI * 2);
    ctx.fill();
  }

  // Moss on the weather side.
  for (let i = 0; i < 260; i++) {
    const x = rng() * w;
    const y = rng() * h;
    ctx.fillStyle = `rgba(${58 + rng() * 32}, ${79 + rng() * 30}, ${40 + rng() * 22}, ${0.05 + rng() * 0.18})`;
    ctx.beginPath();
    ctx.arc(x, y, 1 + rng() * 5, 0, Math.PI * 2);
    ctx.fill();
  }

  const map = new THREE.CanvasTexture(canvas);
  map.wrapS = map.wrapT = THREE.RepeatWrapping;
  map.repeat.set(2, 3);
  map.colorSpace = THREE.SRGBColorSpace;
  map.anisotropy = 4;
  return map;
}

/* ---------- grass tuft ---------- */

export function makeGrassTexture() {
  const rng = mulberry32(8841);
  const w = 128;
  const h = 256;
  const canvas = makeCanvas(w, h);
  const ctx = canvas.getContext('2d');
  ctx.clearRect(0, 0, w, h);

  const blades = 7;
  for (let b = 0; b < blades; b++) {
    const baseX = 34 + rng() * 60;
    const tipX = baseX + (rng() - 0.5) * 58;
    const tipY = 8 + rng() * 46;
    const width = 3 + rng() * 6;
    const ctrlX = baseX + (tipX - baseX) * 0.22 + (rng() - 0.5) * 18;
    const ctrlY = 120 + rng() * 55;

    const grad = ctx.createLinearGradient(0, h, 0, tipY);
    const hueShift = rng();
    grad.addColorStop(0, `rgba(${74 + hueShift * 36}, ${104 + hueShift * 34}, ${52 + hueShift * 20}, 1)`);
    grad.addColorStop(0.55, `rgba(${116 + hueShift * 38}, ${146 + hueShift * 36}, ${76 + hueShift * 26}, 0.95)`);
    grad.addColorStop(1, `rgba(${172 + hueShift * 34}, ${182 + hueShift * 36}, ${110 + hueShift * 30}, 0.82)`);

    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.moveTo(baseX - width, h);
    ctx.quadraticCurveTo(ctrlX - width * 0.5, ctrlY, tipX, tipY);
    ctx.quadraticCurveTo(ctrlX + width * 0.5, ctrlY, baseX + width, h);
    ctx.closePath();
    ctx.fill();
  }

  const map = new THREE.CanvasTexture(canvas);
  map.colorSpace = THREE.SRGBColorSpace;
  map.anisotropy = 4;
  return map;
}

