    else tmpQuat.setFromAxisAngle(up, rotY);
    tmpScale.set(sx, sy, sz);
    return new THREE.Matrix4().compose(tmpPos, tmpQuat, tmpScale);
  }

  function addTree(x, z, kind, scale = 1, elder = false) {
    const y = heightAt(x, z);
    const rotY = rng() * Math.PI * 2;

    if (kind === 'pine') {
      const h = (7 + rng() * 9) * scale * (elder ? 2.1 : 1);
      const radius = (0.2 + h * 0.019) * (elder ? 1.35 : 1);
      const baseR = (elder ? h * 0.19 : h * (0.145 + rng() * 0.04));
      const trunkColor = vary(rng, 0x4a4033, 0x70604a, rng()).multiplyScalar(0.82 + rng() * 0.25);
      trunks.push({
        matrix: matrixAt(x, y + h / 2, z, radius, h, radius, rotY),
        color: trunkColor,
      });

      const layers = elder ? 7 : 5;
      for (let i = 0; i < layers; i++) {
        const t = i / (layers - 1);
        const layerBase = h * (0.18 + t * 0.58);
        const layerHeight = h * (0.4 - t * 0.08);
        const layerRadius = baseR * (1 - t * 0.76) * (0.92 + rng() * 0.14);
        const color = vary(rng, pick(rng, PINE_GREENS), pick(rng, PINE_GREENS), rng());
        color.multiplyScalar(0.86 + rng() * 0.25);
        pines.push({
          matrix: matrixAt(x, y + layerBase, z, layerRadius, layerHeight, layerRadius, rotY + i * 0.6),
          color,
        });
      }
      // A ragged little crown spike.
      pines.push({
        matrix: matrixAt(x, y + h * 0.93, z, baseR * 0.16, h * 0.24, baseR * 0.16, rotY),
        color: vary(rng, 0x2c5033, 0x4d7040, rng()),
      });

      if (elder) addCollider(x, z, radius + 0.8);
      else if (Math.hypot(x, z) < 106) addCollider(x, z, radius + 0.32);
    } else if (kind === 'broadleaf') {
      const birch = rng() < 0.2;
      const h = (5.2 + rng() * 6.5) * scale;
      const radius = 0.18 + h * 0.018;
      const trunkColor = birch
        ? vary(rng, 0xbdb9a2, 0xdedac4, rng())
        : vary(rng, 0x4d4033, 0x75634a, rng()).multiplyScalar(0.82 + rng() * 0.25);
      trunks.push({
        matrix: matrixAt(x, y + h / 2, z, radius, h, radius, rotY),
        color: trunkColor,
      });

      const blobs = 4 + Math.floor(rng() * 3);
      const autumn = rng() < 0.11;
      for (let i = 0; i < blobs; i++) {
        const a = (i / blobs) * Math.PI * 2 + rng() * 0.9;
        const spread = h * (0.1 + rng() * 0.12);
        const bx = x + Math.cos(a) * spread;
        const bz = z + Math.sin(a) * spread;
        const by = y + h * (0.82 + rng() * 0.2);
        const s = h * (0.19 + rng() * 0.09);
        const color = autumn
          ? vary(rng, pick(rng, AUTUMN), pick(rng, AUTUMN), rng())
          : vary(rng, pick(rng, LEAF_GREENS), pick(rng, LEAF_GREENS), rng());
        color.multiplyScalar(0.86 + rng() * 0.24);
        leaves.push({
          matrix: matrixAt(bx, by, bz, s * (0.85 + rng() * 0.4), s * (0.8 + rng() * 0.35), s, rng() * 6),
          color,
        });
      }
      // A lower skirt of shade leaves.
      const skirt = 2 + Math.floor(rng() * 2);
      for (let i = 0; i < skirt; i++) {
        const a = rng() * Math.PI * 2;
        const spread = h * (0.18 + rng() * 0.12);
        const s = h * (0.12 + rng() * 0.05);
        leaves.push({
          matrix: matrixAt(x + Math.cos(a) * spread, y + h * (0.6 + rng() * 0.12), z + Math.sin(a) * spread, s, s * 0.7, s, rng() * 6),
          color: vary(rng, 0x365730, 0x50733c, rng()),
        });
      }

      if (Math.hypot(x, z) < 106) addCollider(x, z, radius + 0.3);
    } else {
      // A leaning, weathered dead tree.
      const h = (5 + rng() * 8) * scale;
      const radius = 0.16 + rng() * 0.14;
      const trunkColor = vary(rng, 0x6b6557, 0x8b8473, rng());
      const leanX = (rng() - 0.5) * 0.7;
      const leanZ = (rng() - 0.5) * 0.7;
      const q = new THREE.Quaternion().setFromEuler(new THREE.Euler(leanX, rotY, leanZ));
      trunks.push({
        matrix: matrixAt(x, y + h / 2, z, radius, h, radius, 0, q),
        color: trunkColor,
      });

      const branchCount = 2 + Math.floor(rng() * 3);
      for (let i = 0; i < branchCount; i++) {
        const by = y + h * (0.35 + rng() * 0.5);
        const a = rng() * Math.PI * 2;
        const len = 1.2 + rng() * 2.4;
        dir.set(Math.cos(a), 0.15 + rng() * 0.6, Math.sin(a)).normalize();
        const bq = new THREE.Quaternion().setFromUnitVectors(up, dir);
        branches.push({
          matrix: matrixAt(x + dir.x * len * 0.45, by + dir.y * len * 0.45, z + dir.z * len * 0.45, radius * 0.42, len, radius * 0.42, 0, bq),
          color: trunkColor,
        });
      }
      if (Math.hypot(x, z) < 106) addCollider(x, z, radius + 0.28);
    }

    placed.push({ x, z, r: 3.1 * scale });
  }

  /* ---------- main forest ---------- */
  const targetTrees = 790;
  let guard = 0;
  while (placed.length < targetTrees && guard < 16000) {
    guard++;
    const x = (rng() * 2 - 1) * 122;
    const z = (rng() * 2 - 1) * 122;
    const radius = Math.hypot(x, z);
    if (radius > 123) continue;
    if (radius < 13.5) continue;
    if (pathDistance(x, z) < 4.2) continue;
    if (rng() < 0.1 && pathDistance(x, z) < 8) continue;

    const dx = heightAt(x + 0.7, z) - heightAt(x - 0.7, z);
    const dz = heightAt(x, z + 0.7) - heightAt(x, z - 0.7);
    if (Math.hypot(dx, dz) / 1.4 > 0.95) continue;

    let crowded = false;
    for (let i = 0; i < placed.length; i++) {
      const p = placed[i];
      const ddx = p.x - x;
      const ddz = p.z - z;
      if (ddx * ddx + ddz * ddz < p.r * p.r) { crowded = true; break; }
    }
    if (crowded) continue;

    const roll = rng();
    const kind = roll < 0.54 ? 'pine' : roll < 0.9 ? 'broadleaf' : 'dead';
    addTree(x, z, kind, 0.8 + rng() * 0.5);
  }

  /* ---------- the elder pine ---------- */
  addTree(27, -45, 'pine', 1.15, true);

  /* ---------- dense edge wall ---------- */
  for (let i = 0; i < 170; i++) {
    const a = rng() * Math.PI * 2;
    const radius = 108 + rng() * 18;
    const x = Math.cos(a) * radius;
    const z = Math.sin(a) * radius;
    addTree(x, z, rng() < 0.82 ? 'pine' : 'broadleaf', 0.9 + rng() * 0.5);
  }

  const trunkMesh = createInstanced(scene, trunkGeometry, barkMaterial, trunks);
  const pineMesh = createInstanced(scene, pineGeometry, pineMaterial, pines);
  const leafMesh = createInstanced(scene, leafGeometry, leafMaterial, leaves);
  const branchMesh = createInstanced(scene, branchGeometry, branchMaterial, branches, false);
  if (branchMesh) branchMesh.castShadow = true;

  /* ---------- fallen logs ---------- */
  const logMaterials = [
    new THREE.MeshStandardMaterial({ map: barkTexture, color: 0x9b8568, roughness: 1 }),
    new THREE.MeshStandardMaterial({ map: barkTexture, color: 0x7f725d, roughness: 1 }),
    new THREE.MeshStandardMaterial({ map: barkTexture, color: 0x8c7a5d, roughness: 1 }),
  ];
  const logGeometry = new THREE.CylinderGeometry(0.82, 1, 1, 9, 1);
  const logGroup = new THREE.Group();
  for (let i = 0; i < 19; i++) {
    let x = 0;
    let z = 0;
    let ok = false;
    for (let tries = 0; tries < 40; tries++) {
      x = (rng() * 2 - 1) * 102;
      z = (rng() * 2 - 1) * 102;
      if (Math.hypot(x, z) < 16) continue;
      if (pathDistance(x, z) < 5) continue;
      ok = true;
      break;
    }
    if (!ok) continue;

    const length = 3.2 + rng() * 5.2;
    const radius = 0.24 + rng() * 0.27;
    const angle = rng() * Math.PI * 2;
    const mesh = new THREE.Mesh(logGeometry, logMaterials[i % logMaterials.length]);
    const d = new THREE.Vector3(Math.cos(angle), 0, Math.sin(angle));
    mesh.quaternion.setFromUnitVectors(up, d);
    mesh.scale.set(radius, length, radius);
    mesh.position.set(x, heightAt(x, z) + radius * 0.92, z);
    mesh.castShadow = true;
    mesh.receiveShadow = true;
    logGroup.add(mesh);

    if (Math.hypot(x, z) < 104) {
      for (const t of [-0.32, 0, 0.32]) {
        addCollider(x + d.x * length * t, z + d.z * length * t, radius + 0.25);
      }
    }
  }
  scene.add(logGroup);

  /* ---------- stumps ---------- */
  const stumpGeometry = new THREE.CylinderGeometry(0.9, 1, 1, 8, 1);
  const stumpCapGeometry = new THREE.CircleGeometry(1, 12);
  stumpCapGeometry.rotateX(-Math.PI / 2);
  const capMaterial = new THREE.MeshStandardMaterial({ color: 0xac8e60, roughness: 0.86 });
  for (let i = 0; i < 23; i++) {
    let x = 0;
    let z = 0;
    for (let tries = 0; tries < 30; tries++) {
      x = (rng() * 2 - 1) * 104;
      z = (rng() * 2 - 1) * 104;
      if (Math.hypot(x, z) < 14) continue;
      if (pathDistance(x, z) < 3.8) continue;
      break;
    }
    const h = 0.35 + rng() * 0.9;
    const r = 0.38 + rng() * 0.35;
    const y = heightAt(x, z);
    stumps.push({
      matrix: matrixAt(x, y + h / 2, z, r, h, r, rng() * 6),
      color: vary(rng, 0x66553f, 0x8b7557, rng()),
    });
    stumpTops.push({
      matrix: matrixAt(x, y + h + 0.008, z, r * 0.98, 1, r * 0.98, rng() * 6),
      color: vary(rng, 0xad8d5d, 0xc9aa79, rng()),
    });
    if (Math.hypot(x, z) < 104) addCollider(x, z, r + 0.2);
  }
  createInstanced(scene, stumpGeometry, barkMaterial, stumps);
  const capMesh = createInstanced(scene, stumpCapGeometry, capMaterial, stumpTops, false);
  if (capMesh) capMesh.castShadow = false;

  return {
    trunkMesh,
    pineMesh,
    leafMesh,
    branchMesh,
    logGroup,
    counts: { trunks: trunks.length, pines: pines.length, leaves: leaves.length },
    elderPine: new THREE.Vector3(27, heightAt(27, -45), -45),
  };
}

import * as THREE from '../vendor/three.module.min.js';
import { mulberry32 } from './noise.js';
import { makeGrassTexture, makeLeafTexture, makeSoftDotTexture } from './textures.js';

/* ============================================================
   Understory: grass, ferns, shrubs, stones, flowers, fungi
   ============================================================ */

const GRASS_COLORS = [0xd8e6c2, 0xc4d8a8, 0xb9cf9e, 0xe3e6bd, 0xcbd7ad, 0xaec895];
const FERN_COLORS = [0x365b2f, 0x436a35, 0x50773a, 0x5d8442, 0x6b8d47];
const ROCK_COLORS = [0x69695c, 0x777468, 0x5f6258, 0x7e7c6d, 0x6b7164, 0x828072];
const BUSH_COLORS = [0x35582f, 0x406636, 0x4a703b, 0x557a40, 0x628447];

function pick(rng, array) { return array[Math.floor(rng() * array.length)]; }

function buildInstanced(scene, geometry, material, items, { cast = false, receive = true } = {}) {
  if (!items.length) return null;
  const mesh = new THREE.InstancedMesh(geometry, material, items.length);
  for (let i = 0; i < items.length; i++) {
    mesh.setMatrixAt(i, items[i].matrix);
    if (items[i].color) mesh.setColorAt(i, items[i].color);
  }
  mesh.instanceMatrix.needsUpdate = true;
  if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true;
  mesh.castShadow = cast;
  mesh.receiveShadow = receive;
  mesh.frustumCulled = false;
  scene.add(mesh);
  return mesh;
}

function deform(geometry, amount, seed) {
  const rng = mulberry32(seed);
  const pos = geometry.attributes.position;
  for (let i = 0; i < pos.count; i++) {
    const x = pos.getX(i);
    const y = pos.getY(i);
    const z = pos.getZ(i);
    const len = Math.sqrt(x * x + y * y + z * z) || 1;
    const k = 1 + (rng() - 0.5) * amount;
    pos.setXYZ(i, (x / len) * k, (y / len) * k, (z / len) * k);
  }
  geometry.computeVertexNormals();
  return geometry;
}

function makeWindMaterial(material, windUniform, strength) {
  material.onBeforeCompile = (shader) => {
    shader.uniforms.uWindTime = windUniform;
    shader.vertexShader = 'uniform float uWindTime;\n' + shader.vertexShader;
    shader.vertexShader = shader.vertexShader.replace(
      '#include <begin_vertex>',
      `#include <begin_vertex>
      #ifdef USE_INSTANCING
        vec3 iPos = vec3(instanceMatrix[3][0], instanceMatrix[3][1], instanceMatrix[3][2]);
        float bend = uv.y * uv.y;
        float w = sin(uWindTime * 1.35 + iPos.x * 0.23 + iPos.z * 0.19) * ${strength.toFixed(3)};
        w += sin(uWindTime * 2.7 + iPos.x * 0.61 + iPos.z * 0.17) * ${(strength * 0.28).toFixed(3)};
        transformed.x += w * bend;
        transformed.z += w * 0.55 * bend;
      #endif`
    );
  };
  material.customProgramCacheKey = () => `wind-${strength}`;
  return material;
}

function makeFernGeometry(seed) {
  const rng = mulberry32(seed);
  const positions = [];
  const uvs = [];
  const indices = [];
  const fronds = 8;
  let v = 0;

  for (let f = 0; f < fronds; f++) {
    const angle = (f / fronds) * Math.PI * 2 + (rng() - 0.5) * 0.5;
    const length = 0.78 + rng() * 0.45;
    const segs = 6;
    const cos = Math.cos(angle);
    const sin = Math.sin(angle);
    const perpX = Math.cos(angle + Math.PI / 2);
    const perpZ = Math.sin(angle + Math.PI / 2);
    const baseIndex = v;

    for (let s = 0; s <= segs; s++) {
      const t = s / segs;
      const dist = t * length;
      const x = cos * dist;
      const z = sin * dist;
      const y = 0.04 + Math.sin(t * Math.PI) * (0.34 + rng() * 0.03) - t * 0.06;
      const width = (1 - t) * 0.115 + 0.006;
      positions.push(x + perpX * width, y, z + perpZ * width);
      uvs.push(0, t);
      positions.push(x - perpX * width, y, z - perpZ * width);
      uvs.push(1, t);
      if (s < segs) {
        const a = baseIndex + s * 2;
        indices.push(a, a + 1, a + 2, a + 1, a + 3, a + 2);
      }
      v += 2;
    }
  }

  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
  geometry.setAttribute('uv', new THREE.Float32BufferAttribute(uvs, 2));
  geometry.setIndex(indices);
  geometry.computeVertexNormals();
  return geometry;
}

export function buildUnderstory({
  scene,
  heightAt,
  pathDistance,
  addCollider,
  wind,
  seed = 5521,
}) {
  const rng = mulberry32(seed);
  const up = new THREE.Vector3(0, 1, 0);

  const mat4 = (x, y, z, sx, sy, sz, rot) => {
    const q = new THREE.Quaternion().setFromAxisAngle(up, rot);
    return new THREE.Matrix4().compose(
      new THREE.Vector3(x, y, z),
      q,
      new THREE.Vector3(sx, sy, sz)
    );
  };

  /* ---------------- grass ---------------- */

  const grassTexture = makeGrassTexture();
  const grassGeometry = new THREE.PlaneGeometry(1, 1, 1, 2);
  grassGeometry.translate(0, 0.5, 0);
  const grassMaterial = makeWindMaterial(
    new THREE.MeshStandardMaterial({
      map: grassTexture,
      alphaTest: 0.32,
      side: THREE.DoubleSide,
      roughness: 1,
      metalness: 0,
      color: 0xffffff,
    }),
    wind,
    0.085
  );

  const grassItems = [];
  const grassTotal = 18000;
  for (let i = 0; i < grassTotal; i++) {
    const x = (rng() * 2 - 1) * 122;
    const z = (rng() * 2 - 1) * 122;
    if (Math.hypot(x, z) > 124) continue;
    if (pathDistance(x, z) < 1.45) continue;
    const scale = 0.52 + rng() * 0.85;
    const y = heightAt(x, z) + 0.01;
    grassItems.push({
      matrix: mat4(x, y, z, scale * (0.7 + rng() * 0.5), scale, 1, rng() * Math.PI * 2),
      color: new THREE.Color(pick(rng, GRASS_COLORS)).multiplyScalar(0.86 + rng() * 0.24),
    });
  }
  // Extra lushness crowding the trail edges.
  for (let i = 0; i < 3600; i++) {
    const angle = rng() * Math.PI * 2;
    const dist = 1.7 + rng() * 7;
    const t = rng();
    // Sample along the trail polyline approximately by picking a random point nearby.
    const bx = Math.sin(t * 18) * 12 + (rng() - 0.5) * 8;
    const bz = 12 - t * 120 + (rng() - 0.5) * 8;
    const x = bx + Math.cos(angle) * dist;
    const z = bz + Math.sin(angle) * dist;
    if (pathDistance(x, z) < 1.55 || Math.hypot(x, z) > 122) continue;
    const scale = 0.6 + rng() * 1.05;
    grassItems.push({
      matrix: mat4(x, heightAt(x, z) + 0.01, z, scale * (0.7 + rng() * 0.5), scale, 1, rng() * Math.PI * 2),
      color: new THREE.Color(pick(rng, GRASS_COLORS)).multiplyScalar(0.88 + rng() * 0.2),
    });
  }
  const grass = buildInstanced(scene, grassGeometry, grassMaterial, grassItems);

  /* ---------------- ferns ---------------- */

  const fernGeometry = makeFernGeometry(118);
  const fernMaterial = makeWindMaterial(
    new THREE.MeshStandardMaterial({
      color: 0xffffff,
      roughness: 0.9,
      metalness: 0,
      side: THREE.DoubleSide,
      flatShading: true,
    }),
    wind,
    0.045
  );
  const fernItems = [];
  for (let i = 0; i < 640; i++) {
    const x = (rng() * 2 - 1) * 112;
    const z = (rng() * 2 - 1) * 112;
    const r = Math.hypot(x, z);
    if (r < 11 || r > 118) continue;
    const pd = pathDistance(x, z);
    if (pd < 2.1) continue;
    if (pd > 10 && rng() > 0.55) continue;
    const scale = 0.65 + rng() * 0.85;
    fernItems.push({
      matrix: mat4(x, heightAt(x, z) + 0.02, z, scale, scale * (0.75 + rng() * 0.4), scale, rng() * Math.PI * 2),
      color: new THREE.Color(pick(rng, FERN_COLORS)).multiplyScalar(0.85 + rng() * 0.25),
    });
  }
  // Ferns gathered around the spawning glade.
  for (let i = 0; i < 160; i++) {
    const a = rng() * Math.PI * 2;
    const r = 12 + rng() * 13;
    const x = Math.cos(a) * r;
    const z = Math.sin(a) * r;
    if (pathDistance(x, z) < 2.2) continue;
    const scale = 0.65 + rng() * 0.9;
    fernItems.push({
      matrix: mat4(x, heightAt(x, z) + 0.02, z, scale, scale, scale, rng() * Math.PI * 2),
      color: new THREE.Color(pick(rng, FERN_COLORS)).multiplyScalar(0.9 + rng() * 0.2),
    });
  }
  const ferns = buildInstanced(scene, fernGeometry, fernMaterial, fernItems);

  /* ---------------- shrubs ---------------- */

  const bushGeometry = deform(new THREE.IcosahedronGeometry(1, 1), 0.35, 97);
  const bushMaterial = new THREE.MeshStandardMaterial({
    color: 0xffffff,
    roughness: 0.94,
    metalness: 0,
    flatShading: false,
  });
  const bushItems = [];
  for (let i = 0; i < 330; i++) {
    const x = (rng() * 2 - 1) * 116;
    const z = (rng() * 2 - 1) * 116;
    const r = Math.hypot(x, z);
    if (r < 10 || r > 122) continue;
    if (pathDistance(x, z) < 2.8) continue;
    const s = 0.45 + rng() * 1.25;
    bushItems.push({
      matrix: mat4(x, heightAt(x, z) + s * 0.28, z, s * (0.9 + rng() * 0.5), s * (0.6 + rng() * 0.45), s, rng() * 6),
      color: new THREE.Color(pick(rng, BUSH_COLORS)).multiplyScalar(0.9 + rng() * 0.2),
    });
  }
  const bushes = buildInstanced(scene, bushGeometry, bushMaterial, bushItems);

  /* ---------------- stones ---------------- */

  const rockGeometry = deform(new THREE.DodecahedronGeometry(1, 0), 0.34, 73);
  const rockMaterial = new THREE.MeshStandardMaterial({
    color: 0xffffff,
    roughness: 0.97,
    metalness: 0,
    flatShading: true,
  });
  const rockItems = [];
  function addRock(x, z, s, yOffset = 0.24) {
    const sy = s * (0.55 + rng() * 0.6);
    rockItems.push({
      matrix: mat4(x, heightAt(x, z) + sy * yOffset, z, s * (0.85 + rng() * 0.45), sy, s * (0.85 + rng() * 0.45), rng() * 6),
      color: new THREE.Color(pick(rng, ROCK_COLORS)).multiplyScalar(0.9 + rng() * 0.2),
    });
  }
  for (let i = 0; i < 250; i++) {
    const x = (rng() * 2 - 1) * 118;
    const z = (rng() * 2 - 1) * 118;
    if (Math.hypot(x, z) > 121) continue;
    if (pathDistance(x, z) < 1.9) continue;
    const big = rng() < 0.08;
    const s = big ? 1.1 + rng() * 1.5 : 0.15 + rng() * 0.55;
    addRock(x, z, s);
    if (big && Math.hypot(x, z) < 105) addCollider(x, z, s * 0.9);
  }
  // Trail-side stepping stones and pebbles.
  for (let i = 0; i < 120; i++) {
    const t = rng();
    const x = Math.sin(t * 18) * 12 + (rng() - 0.5) * 3.6;
    const z = 12 - t * 120;
    if (Math.abs(x) < 1 && rng() < 0.6) continue;
    addRock(x, z, 0.12 + rng() * 0.28, 0.1);
  }
  // A ring of mossy stones on the southern bank.
  for (let i = 0; i < 9; i++) {
    const a = (i / 9) * Math.PI * 2;
    const x = 14 + Math.cos(a) * 6.4;
    const z = 41 + Math.sin(a) * 6.4;
    addRock(x, z, 0.9 + rng() * 0.7, 0.22);
    addCollider(x, z, 0.8);
  }
  // A big split boulder west of the trail.
  addRock(-34, -20, 3.2, 0.18);
  addRock(-30.8, -18.6, 1.7, 0.2);
  addCollider(-34, -20, 2.6);
  addCollider(-30.8, -18.6, 1.4);

  const rocks = buildInstanced(scene, rockGeometry, rockMaterial, rockItems, { cast: true });

  /* ---------------- flowers (points) ---------------- */

  const flowerPositions = [];
  const flowerColors = [];
  const flowerPalette = [0xfff1c4, 0xffe08a, 0xf5f0dd, 0xd8c7f0, 0xf5c7b6, 0xffd7e2];
  for (let i = 0; i < 1200; i++) {
    const x = (rng() * 2 - 1) * 112;
    const z = (rng() * 2 - 1) * 112;
    const r = Math.hypot(x, z);
    if (r < 10 || r > 116) continue;
    const pd = pathDistance(x, z);
    if (pd < 1.3) continue;
    if (pd > 8 && rng() > 0.35) continue;
    flowerPositions.push(x, heightAt(x, z) + 0.14 + rng() * 0.28, z);
    const c = new THREE.Color(pick(rng, flowerPalette));
    flowerColors.push(c.r, c.g, c.b);
  }
  const flowerGeometry = new THREE.BufferGeometry();
  flowerGeometry.setAttribute('position', new THREE.Float32BufferAttribute(flowerPositions, 3));
  flowerGeometry.setAttribute('color', new THREE.Float32BufferAttribute(flowerColors, 3));
  const flowerMaterial = new THREE.PointsMaterial({
    size: 0.13,
    map: makeSoftDotTexture(),
    alphaTest: 0.2,
    transparent: true,
    opacity: 0.9,
    vertexColors: true,
    sizeAttenuation: true,
    depthWrite: true,
  });
  const flowers = new THREE.Points(flowerGeometry, flowerMaterial);
  flowers.frustumCulled = false;
  scene.add(flowers);

  /* ---------------- mushrooms ---------------- */

  const stemGeometry = new THREE.CylinderGeometry(0.07, 0.11, 1, 5);
  stemGeometry.translate(0, 0.5, 0);
  const capGeometry = new THREE.SphereGeometry(1, 8, 4, 0, Math.PI * 2, 0, Math.PI / 2);
  const stemMaterial = new THREE.MeshStandardMaterial({ color: 0xd8cfba, roughness: 0.96 });
  const capMaterial = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.82, flatShading: true });
  const mushroomPalette = [0xa9472e, 0xc2672f, 0xd9a44d, 0x8f6a45, 0xe0d6ba, 0x7d5636];
  const stems = [];
  const caps = [];
  let mushroomGuard = 0;
  while (stems.length < 210 && mushroomGuard < 900) {
    mushroomGuard++;
    const x = (rng() * 2 - 1) * 108;
    const z = (rng() * 2 - 1) * 108;
    const r = Math.hypot(x, z);
    if (r < 12 || r > 114) continue;
    if (pathDistance(x, z) < 2) continue;
    const y = heightAt(x, z);
    const cluster = 1 + Math.floor(rng() * 3);
    for (let c = 0; c < cluster && stems.length < 210; c++) {
      const ox = (rng() - 0.5) * 0.7;
      const oz = (rng() - 0.5) * 0.7;
      const h = 0.11 + rng() * 0.26;
      const capR = 0.08 + rng() * 0.16;
      const rot = rng() * Math.PI * 2;
      stems.push({
        matrix: mat4(x + ox, y, z + oz, 1, h, 1, rot),
      });
      caps.push({
        matrix: mat4(x + ox, y + h, z + oz, capR, capR * (0.45 + rng() * 0.2), capR, rot),
        color: new THREE.Color(pick(rng, mushroomPalette)),
      });
    }
  }
  const stemMesh = buildInstanced(scene, stemGeometry, stemMaterial, stems, { cast: false });
  const capMesh = buildInstanced(scene, capGeometry, capMaterial, caps, { cast: false });

  /* ---------------- leaf litter ---------------- */

  const leafTexture = makeLeafTexture();
  const leafGeometry = new THREE.PlaneGeometry(0.34, 0.2);
  leafGeometry.rotateX(-Math.PI / 2);
  const leafMaterial = new THREE.MeshStandardMaterial({
    map: leafTexture,
    alphaTest: 0.35,
    side: THREE.DoubleSide,
    roughness: 1,
    color: 0xffffff,
  });
  const leafItems = [];
  const leafPalette = [0xb18b4f, 0x9a7442, 0xc3a263, 0x8a6638, 0xb79a5f, 0x7d6239, 0xc4b178];
  for (let i = 0; i < 3200; i++) {
    const x = (rng() * 2 - 1) * 114;
    const z = (rng() * 2 - 1) * 114;
    if (Math.hypot(x, z) > 118) continue;
    if (pathDistance(x, z) < 1.8) continue;
    const s = 0.55 + rng() * 1.15;
    leafItems.push({
      matrix: mat4(x, heightAt(x, z) + 0.012, z, s, 1, s, rng() * Math.PI * 2),
      color: new THREE.Color(pick(rng, leafPalette)).multiplyScalar(0.85 + rng() * 0.25),
    });
  }
  const leafLitter = buildInstanced(scene, leafGeometry, leafMaterial, leafItems, { cast: false, receive: false });

  /* ---------------- potato controls ---------------- */

  const full = {
    grass: grassItems.length,
    ferns: fernItems.length,
    leaves: leafItems.length,
  };

  function setPotato(on) {
    if (grass) grass.count = on ? 900 : full.grass;
    if (ferns) ferns.count = on ? 80 : full.ferns;
    if (leafLitter) leafLitter.count = on ? 0 : full.leaves;
    if (flowers) flowers.visible = !on;
    if (mushroomCap) mushroomCap.visible = !on;
    if (stemMesh) stemMesh.visible = !on;
    if (bushes) bushes.visible = true;
    if (rocks) rocks.visible = true;
  }

  const mushroomCap = capMesh;

  return {
    grass,
    ferns,
    bushes,
    rocks,
    flowers,
    mushrooms: { stems: stemMesh, caps: capMesh },
    leafLitter,
    setPotato,
    counts: full,
  };
}

import * as THREE from '../vendor/three.module.min.js';
import { mulberry32, fbm, smoothstep, clamp } from './noise.js';
import { makeGroundMaps, makePathTexture, makeBarkTexture, makeSoftDotTexture } from './textures.js';
import { buildTrees } from './trees.js';
import { buildUnderstory } from './understory.js';

/* ============================================================
   Silverpine Wilds — world assembly
   ============================================================ */

const WORLD_SIZE = 260;
const PLAY_RADIUS = 102;
const CELL = 8;

const TRAIL_POINTS = [
  [0.4, 18], [0.2, 9], [0.8, 0], [1.8, -9], [3.2, -19],
  [-0.8, -30], [-2.8, -41], [1.8, -52], [-4.2, -63],
  [-10.8, -73], [-10.6, -84], [-13.8, -95], [-21.5, -108],
];

const SUN_DIR = new THREE.Vector3(0.46, 0.34, -0.56).normalize();

export function createWorld(scene, renderer) {
  const rng = mulberry32(20261104);
  const wind = { value: 0 };

  /* ---------- trail polyline ---------- */
  const trailCurve = new THREE.CatmullRomCurve3(
    TRAIL_POINTS.map(([x, z]) => new THREE.Vector3(x, 0, z)),
    false,
    'catmullrom',
    0.5
  );
  const trailSamples = trailCurve.getPoints(210);

  function pathDistance(x, z) {
    let best = Infinity;
    for (let i = 0; i < trailSamples.length - 1; i++) {
      const a = trailSamples[i];
      const b = trailSamples[i + 1];
      const dx = b.x - a.x;
      const dz = b.z - a.z;
      const len2 = dx * dx + dz * dz;
      let t = 0;
      if (len2 > 0) t = clamp(((x - a.x) * dx + (z - a.z) * dz) / len2, 0, 1);
      const px = a.x + dx * t - x;
      const pz = a.z + dz * t - z;
      const d2 = px * px + pz * pz;
      if (d2 < best) best = d2;
    }
    return Math.sqrt(best);
  }

  /* ---------- terrain height ---------- */
  function heightAt(x, z) {
    const radius = Math.hypot(x, z);
    let h = (fbm(x * 0.0115 + 4.3, z * 0.0115 - 2.1, 5) - 0.5) * 15;
    h += (fbm(x * 0.032 - 7.2, z * 0.032 + 3.4, 4) - 0.5) * 3.6;
    h += (fbm(x * 0.086 + 1.2, z * 0.086 + 8.9, 2) - 0.5) * 0.55;
    // A wide, quiet bowl around the starting glade.
    h *= smoothstep(10, 42, radius);
    // Forested rim that keeps the horizon closed.
    const edge = smoothstep(88, 128, radius);
    h += edge * edge * 17 + edge * (fbm(x * 0.021 + 9, z * 0.021 - 4, 3) - 0.34) * 8;
    return h;
  }

  const spawn = new THREE.Vector3(0.4, 0, 8.5);
  spawn.y = heightAt(spawn.x, spawn.z);

  /* ---------- renderer basics ---------- */
  renderer.outputColorSpace = THREE.SRGBColorSpace;
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.03;
  renderer.shadowMap.enabled = true;
  renderer.shadowMap.type = THREE.PCFSoftShadowMap;
  scene.background = new THREE.Color(0xb7c5ad);
  scene.fog = new THREE.FogExp2(0xb7c5ad, 0.0086);

  /* ---------- sky ---------- */
  const skyUniforms = {
    uTop: { value: new THREE.Color(0x5f8794) },
    uHorizon: { value: new THREE.Color(0xe4d0a8) },
    uSunColor: { value: new THREE.Color(0xffdda0) },
    uSun: { value: SUN_DIR.clone() },
    uTime: { value: 0 },
    uCloud: { value: 1 },
  };
  const skyGeometry = new THREE.SphereGeometry(430, 32, 18);
  const skyMaterial = new THREE.ShaderMaterial({
    uniforms: skyUniforms,
    side: THREE.BackSide,
    depthWrite: false,
    fog: false,
    vertexShader: `
      varying vec3 vWorldPosition;
      void main() {
        vWorldPosition = (modelMatrix * vec4(position, 1.0)).xyz;
        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
      }
    `,
    fragmentShader: `
      uniform vec3 uTop;
      uniform vec3 uHorizon;
      uniform vec3 uSunColor;
      uniform vec3 uSun;
      uniform float uTime;
      uniform float uCloud;
      varying vec3 vWorldPosition;

      float hash21(vec2 p) {
        p = fract(p * vec2(123.34, 456.21));
        p += dot(p, p + 45.32);
        return fract(p.x * p.y);
      }
      float vnoise(vec2 p) {
        vec2 i = floor(p);
        vec2 f = fract(p);
        f = f * f * (3.0 - 2.0 * f);
        float a = hash21(i);
        float b = hash21(i + vec2(1.0, 0.0));
        float c = hash21(i + vec2(0.0, 1.0));
        float d = hash21(i + vec2(1.0, 1.0));
        return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
      }
      float cloudNoise(vec2 p) {
        float v = 0.0;
        float a = 0.55;
        for (int i = 0; i < 5; i++) {
          v += vnoise(p) * a;
          p = p * 2.02 + vec2(13.1, 7.7);
          a *= 0.5;
        }
        return v;
      }

      void main() {
        vec3 dir = normalize(vWorldPosition - cameraPosition);
        float h = clamp(dir.y, 0.0, 1.0);
        vec3 col = mix(uHorizon, uTop, pow(h, 0.52));

        float sd = max(dot(dir, uSun), 0.0);
        col += uSunColor * (pow(sd, 780.0) * 1.7 + pow(sd, 11.0) * 0.18);
        col += uSunColor * pow(max(1.0 - h, 0.0), 5.0) * 0.045;

        if (dir.y > 0.012) {
          vec2 sp = dir.xz / (dir.y + 0.2);
          vec2 uv = sp * 0.95 + vec2(uTime * 0.0022, uTime * 0.0008);
          float n = cloudNoise(uv * 1.2) * 0.72 + cloudNoise(uv * 2.35 + 9.0) * 0.28;
          float cloud = smoothstep(0.5, 0.76, n) * smoothstep(0.0, 0.32, dir.y);
          cloud *= uCloud;
          vec3 cloudCol = mix(vec3(0.78, 0.76, 0.67), vec3(1.0, 0.92, 0.74), pow(sd, 2.0));
          col = mix(col, cloudCol, cloud * 0.52);
        }

        // Slight haze band where the sky meets the canopy.
        col = mix(col, uHorizon, smoothstep(0.1, -0.04, dir.y) * 0.32);

        gl_FragColor = vec4(col, 1.0);
        #include <tonemapping_fragment>
        #include <colorspace_fragment>
      }
    `,
  });
  const sky = new THREE.Mesh(skyGeometry, skyMaterial);
  sky.frustumCulled = false;
  sky.renderOrder = -10;
  scene.add(sky);

  /* ---------- lights ---------- */
  const sun = new THREE.DirectionalLight(0xffdfac, 3.1);
  sun.castShadow = true;
  sun.shadow.mapSize.set(2048, 2048);
  sun.shadow.camera.left = -46;
  sun.shadow.camera.right = 46;
  sun.shadow.camera.top = 46;
  sun.shadow.camera.bottom = -46;
  sun.shadow.camera.near = 1;
  sun.shadow.camera.far = 190;
  sun.shadow.bias = -0.00055;
  sun.shadow.normalBias = 0.035;
  scene.add(sun);
  scene.add(sun.target);

  const hemi = new THREE.HemisphereLight(0xc3d8c6, 0x33291b, 1.12);
  scene.add(hemi);
  const ambient = new THREE.AmbientLight(0x74836e, 0.28);
  scene.add(ambient);

  /* ---------- terrain ---------- */
  const groundMaps = makeGroundMaps();
  const groundGeometry = new THREE.PlaneGeometry(WORLD_SIZE, WORLD_SIZE, 200, 200);
  groundGeometry.rotateX(-Math.PI / 2);
  const groundPos = groundGeometry.attributes.position;
  const groundColors = new Float32Array(groundPos.count * 3);
  const cDeep = new THREE.Color(0x2c3820);
  const cMoss = new THREE.Color(0x4a522b);
  const cLoam = new THREE.Color(0x5b482e);
  const cDirt = new THREE.Color(0x8a7552);
  const cStone = new THREE.Color(0x6b6a5c);
  const cFern = new THREE.Color(0x3c5228);
  const tmpColor = new THREE.Color();

  for (let i = 0; i < groundPos.count; i++) {
    const x = groundPos.getX(i);
    const z = groundPos.getZ(i);
    const y = heightAt(x, z);
    groundPos.setY(i, y);

    const n1 = fbm(x * 0.07 + 20, z * 0.07 - 13, 3);
    const n2 = fbm(x * 0.29 - 5, z * 0.29 + 8, 2);
    const slope = Math.hypot(heightAt(x + 0.9, z) - heightAt(x - 0.9, z), heightAt(x, z + 0.9) - heightAt(x, z - 0.9)) / 1.8;
    const pd = pathDistance(x, z);

    tmpColor.copy(cDeep);
    tmpColor.lerp(cMoss, smoothstep(0.25, 0.75, n1));
    tmpColor.lerp(cLoam, smoothstep(0.45, 0.9, n2) * 0.55);
    tmpColor.lerp(cFern, smoothstep(0.55, 0.95, fbm(x * 0.14 + 5, z * 0.14 - 2, 2)) * 0.4);
    tmpColor.lerp(cStone, smoothstep(0.7, 1.5, slope) * 0.72);
    tmpColor.lerp(cDirt, smoothstep(5.6, 1.2, pd) * 0.92);
    tmpColor.multiplyScalar(0.85 + n2 * 0.28);

    groundColors[i * 3] = tmpColor.r;
    groundColors[i * 3 + 1] = tmpColor.g;
    groundColors[i * 3 + 2] = tmpColor.b;
  }
  groundGeometry.setAttribute('color', new THREE.BufferAttribute(groundColors, 3));
  groundGeometry.computeVertexNormals();

  const groundMaterial = new THREE.MeshStandardMaterial({
    map: groundMaps.map,
    bumpMap: groundMaps.bump,
    bumpScale: 0.32,
    vertexColors: true,
    roughness: 0.985,
    metalness: 0,
  });
  const terrain = new THREE.Mesh(groundGeometry, groundMaterial);
  terrain.receiveShadow = true;
  scene.add(terrain);

  /* ---------- trail ribbon ---------- */
  {
    const ribbonSamples = trailCurve.getPoints(300);
    const vertices = [];
    const uvs = [];
    const indices = [];
    let distance = 0;
    for (let i = 0; i < ribbonSamples.length; i++) {
      const p = ribbonSamples[i];
      const prev = ribbonSamples[Math.max(0, i - 1)];
      const next = ribbonSamples[Math.min(ribbonSamples.length - 1, i + 1)];
      const tx = next.x - prev.x;
      const tz = next.z - prev.z;
      const tl = Math.hypot(tx, tz) || 1;
      const nx = -tz / tl;
      const nz = tx / tl;
      if (i > 0) distance += Math.hypot(p.x - ribbonSamples[i - 1].x, p.z - ribbonSamples[i - 1].z);
      const width = 1.55 + Math.sin(i * 0.21) * 0.16;
      const lx = p.x + nx * width;
      const lz = p.z + nz * width;
      const rx = p.x - nx * width;
      const rz = p.z - nz * width;
      vertices.push(lx, heightAt(lx, lz) + 0.045, lz);
      vertices.push(rx, heightAt(rx, rz) + 0.045, rz);
      uvs.push(0, distance * 0.22, 1, distance * 0.22);
      if (i < ribbonSamples.length - 1) {
        const a = i * 2;
        indices.push(a, a + 2, a + 1, a + 1, a + 2, a + 3);
      }
    }
    const ribbonGeometry = new THREE.BufferGeometry();
    ribbonGeometry.setAttribute('position', new THREE.Float32BufferAttribute(vertices, 3));
    ribbonGeometry.setAttribute('uv', new THREE.Float32BufferAttribute(uvs, 2));
    ribbonGeometry.setIndex(indices);
    ribbonGeometry.computeVertexNormals();
    const ribbonMaterial = new THREE.MeshStandardMaterial({
      map: makePathTexture(),
      transparent: true,
      alphaTest: 0.08,
      roughness: 1,
      metalness: 0,
      polygonOffset: true,
      polygonOffsetFactor: -2,
      polygonOffsetUnits: -2,
    });
    const ribbon = new THREE.Mesh(ribbonGeometry, ribbonMaterial);
    ribbon.receiveShadow = true;
    scene.add(ribbon);
  }

  /* ---------- collision grid ---------- */
  const colliderGrid = new Map();
  function addCollider(x, z, r) {
    const cx = Math.floor(x / CELL);
    const cz = Math.floor(z / CELL);
    const key = `${cx},${cz}`;
    if (!colliderGrid.has(key)) colliderGrid.set(key, []);
    colliderGrid.get(key).push({ x, z, r });
  }

  function resolveCollision(x, z, radius) {
    let px = x;
    let pz = z;
    for (let pass = 0; pass < 2; pass++) {
      const cx = Math.floor(px / CELL);
      const cz = Math.floor(pz / CELL);
      for (let gx = cx - 1; gx <= cx + 1; gx++) {
        for (let gz = cz - 1; gz <= cz + 1; gz++) {
          const list = colliderGrid.get(`${gx},${gz}`);
          if (!list) continue;
          for (let i = 0; i < list.length; i++) {
            const c = list[i];
            let dx = px - c.x;
            let dz = pz - c.z;
            const min = c.r + radius;
            const d2 = dx * dx + dz * dz;
            if (d2 < min * min) {
              let d = Math.sqrt(d2);
              if (d < 0.0001) { dx = 1; dz = 0; d = 1; }
              px = c.x + (dx / d) * min;
              pz = c.z + (dz / d) * min;
            }
          }
        }
      }
    }
    // The forest edge keeps its own counsel.
    const r = Math.hypot(px, pz);
    if (r > PLAY_RADIUS) {
      px = (px / r) * PLAY_RADIUS;
      pz = (pz / r) * PLAY_RADIUS;
    }
    return { x: px, z: pz };
  }

  /* ---------- vegetation ---------- */
  const barkTexture = makeBarkTexture();
  const trees = buildTrees({
    scene,
    heightAt,
    pathDistance,
    addCollider,
    barkTexture,
    seed: 1337,
  });

  const understory = buildUnderstory({
    scene,
    heightAt,
    pathDistance,
    addCollider,
    wind,
    seed: 5521,
  });

  /* ---------- drifting mist ---------- */
  const softDot = makeSoftDotTexture();
  const mistCount = 170;
  const mistPositions = new Float32Array(mistCount * 3);
  const mistBaseY = new Float32Array(mistCount);
  const mistPhase = new Float32Array(mistCount);
  for (let i = 0; i < mistCount; i++) {
    const x = (rng() * 2 - 1) * 118;
    const z = (rng() * 2 - 1) * 118;
    const y = heightAt(x, z) + 0.8 + rng() * 4.2;
    mistPositions[i * 3] = x;
    mistPositions[i * 3 + 1] = y;
    mistPositions[i * 3 + 2] = z;
    mistBaseY[i] = y;
    mistPhase[i] = rng() * Math.PI * 2;
  }
  const mistGeometry = new THREE.BufferGeometry();
  mistGeometry.setAttribute('position', new THREE.BufferAttribute(mistPositions, 3));
  const mistMaterial = new THREE.PointsMaterial({
    size: 18,
    map: softDot,
    transparent: true,
    opacity: 0.055,
    depthWrite: false,
    color: 0xdfe7d6,
    sizeAttenuation: true,
    fog: true,
  });
  const mist = new THREE.Points(mistGeometry, mistMaterial);
  mist.frustumCulled = false;
  scene.add(mist);

  /* ---------- floating pollen ---------- */
  const moteCount = 420;
  const motePositions = new Float32Array(moteCount * 3);
  const moteBase = new Float32Array(moteCount * 3);
  const motePhase = new Float32Array(moteCount);
  for (let i = 0; i < moteCount; i++) {
    const x = (rng() * 2 - 1) * 96;
    const z = (rng() * 2 - 1) * 96;
    const y = heightAt(x, z) + 0.4 + rng() * 4.5;
    motePositions[i * 3] = x;
    motePositions[i * 3 + 1] = y;
    motePositions[i * 3 + 2] = z;
    moteBase[i * 3] = x;
    moteBase[i * 3 + 1] = y;
    moteBase[i * 3 + 2] = z;
    motePhase[i] = rng() * Math.PI * 2;
  }
  const moteGeometry = new THREE.BufferGeometry();
  moteGeometry.setAttribute('position', new THREE.BufferAttribute(motePositions, 3));
  const moteMaterial = new THREE.PointsMaterial({
    size: 0.075,
    map: softDot,
    transparent: true,
    opacity: 0.62,
    depthWrite: false,
    color: 0xffe4b0,
    blending: THREE.AdditiveBlending,
    sizeAttenuation: true,
    fog: true,
  });
  const motes = new THREE.Points(moteGeometry, moteMaterial);
  motes.frustumCulled = false;
  scene.add(motes);

  /* ---------- god rays ---------- */
  const shaftGroup = new THREE.Group();
  const shaftGeometry = new THREE.ConeGeometry(1, 1, 12, 1, true);
  const shaftMaterial = new THREE.MeshBasicMaterial({
    color: 0xffe9bd,
    transparent: true,
    opacity: 0.022,
    depthWrite: false,
    side: THREE.DoubleSide,
    blending: THREE.AdditiveBlending,
    fog: true,
  });
  const raySpots = [
    [-8, -6], [12, -18], [-18, -32], [24, -38], [-2, -52], [34, -8], [-38, 10], [16, 22],
  ];
  for (let i = 0; i < raySpots.length; i++) {
    const [x, z] = raySpots[i];
    const width = 3.4 + rng() * 4.5;
    const height = 34 + rng() * 16;
    const mesh = new THREE.Mesh(shaftGeometry, shaftMaterial.clone());
    mesh.scale.set(width, height, width);
    const groundY = heightAt(x, z);
    mesh.position.set(x, groundY, z).addScaledVector(SUN_DIR, height * 0.5);
    mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), SUN_DIR);
    mesh.frustumCulled = false;
    mesh.renderOrder = 3;
    mesh.material.opacity = 0.012 + rng() * 0.02;
    shaftGroup.add(mesh);
  }
  scene.add(shaftGroup);

  /* ---------- landmarks ---------- */
  const landmarks = [
    { name: 'The Clearing', x: 0, z: 8, r: 18 },
    { name: 'The Elder Pine', x: 27, z: -45, r: 23 },
    { name: 'Fern Gully', x: -66, z: -12, r: 42 },
    { name: 'The Long Hollow', x: -13, z: -84, r: 35 },
    { name: 'Mossbank', x: 14, z: 41, r: 28 },
    { name: 'Sunken Pines', x: 68, z: -58, r: 45 },
    { name: 'The Stone Ring', x: 14, z: 41, r: 11 },
    { name: 'Split Boulder', x: -33, z: -19, r: 15 },
  ];

  /* ---------- quality ---------- */
  let potato = false;
  function setPotato(on) {
    potato = on;
    understory.setPotato(on);
    renderer.shadowMap.enabled = !on;
    sun.castShadow = !on;
    skyUniforms.uCloud.value = on ? 0.22 : 1;
    mist.visible = !on;
    motes.visible = !on;
    shaftGroup.visible = !on;
    scene.fog.density = on ? 0.0108 : 0.0086;
    renderer.shadowMap.needsUpdate = true;
  }

  /* ---------- per-frame atmosphere ---------- */
  function update(time, dt, cameraPos) {
    wind.value = time;
    skyUniforms.uTime.value = time;
    sky.position.copy(cameraPos);

    sun.position.set(
      cameraPos.x + SUN_DIR.x * 85,
      cameraPos.y + SUN_DIR.y * 85,
      cameraPos.z + SUN_DIR.z * 85
    );
    sun.target.position.set(cameraPos.x, heightAt(cameraPos.x, cameraPos.z), cameraPos.z);
    sun.target.updateMatrixWorld();

    if (!potato) {
      const mistPos = mistGeometry.attributes.position;
      for (let i = 0; i < mistCount; i++) {
        const speed = 0.24 + (i % 7) * 0.035;
        let x = mistPos.getX(i) + speed * dt;
        if (x > 124) x -= 248;
        mistPos.setX(i, x);
        mistPos.setY(i, mistBaseY[i] + Math.sin(time * 0.19 + mistPhase[i]) * 0.24);
      }
      mistPos.needsUpdate = true;

      const motePos = moteGeometry.attributes.position;
      for (let i = 0; i < moteCount; i++) {
        const ph = motePhase[i];
        motePos.setX(i, moteBase[i * 3] + Math.sin(time * 0.24 + ph) * 1.15);
        motePos.setY(i, moteBase[i * 3 + 1] + Math.sin(time * 0.5 + ph * 1.7) * 0.34);
        motePos.setZ(i, moteBase[i * 3 + 2] + Math.cos(time * 0.21 + ph) * 1.0);
      }
      motePos.needsUpdate = true;

      for (let i = 0; i < shaftGroup.children.length; i++) {
        const shaft = shaftGroup.children[i];
        shaft.material.opacity = (0.012 + (i % 4) * 0.004) + Math.sin(time * 0.24 + i) * 0.006;
      }
    }
  }

  return {
    heightAt,
    pathDistance,
    resolveCollision,
    spawn,
    landmarks,
    setPotato,
    update,
    sun,
    sky,
    trees,
    understory,
    playRadius: PLAY_RADIUS,
  };
}

/* ============================================================
   Procedural forest ambience — wind, leaves, birds, footsteps
   ============================================================ */

export class ForestAudio {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.noiseBuffer = null;
    this.volume = 0.4;
    this.started = false;
    this.paused = false;
    this.birdTimer = null;
  }

  async start() {
    if (this.started) {
      if (this.ctx?.state === 'suspended') await this.ctx.resume().catch(() => {});
      return;
    }
    const AudioCtx = window.AudioContext || window.webkitAudioContext;
    if (!AudioCtx) return;
    try {
      this.ctx = new AudioCtx();
      await this.ctx.resume().catch(() => {});
      this.master = this.ctx.createGain();
      this.master.gain.value = 0;
      this.master.connect(this.ctx.destination);
      this.noiseBuffer = this.makeNoiseBuffer(4);

      this.wind = this.makeWind();
      this.leaves = this.makeLeaves();
      this.started = true;
      this.setVolume(this.volume);
      this.scheduleBird();
    } catch {
      this.started = false;
    }
  }

  makeNoiseBuffer(seconds, brown = true) {
    const ctx = this.ctx;
    const length = Math.floor(ctx.sampleRate * seconds);
    const buffer = ctx.createBuffer(1, length, ctx.sampleRate);
    const data = buffer.getChannelData(0);
    let last = 0;
    for (let i = 0; i < length; i++) {
      const white = Math.random() * 2 - 1;
      if (brown) {
        last = (last + 0.02 * white) / 1.02;
        data[i] = last * 3.1;
      } else {
        data[i] = white;
      }
    }
    return buffer;
  }

  makeWind() {
    const ctx = this.ctx;
    const src = ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    src.loop = true;

    const filter = ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 380;
    filter.Q.value = 0.6;

    const gain = ctx.createGain();
    gain.gain.value = 0.5;

    const lfo = ctx.createOscillator();
    lfo.frequency.value = 0.075;
    const lfoGain = ctx.createGain();
    lfoGain.gain.value = 160;
    lfo.connect(lfoGain).connect(filter.frequency);

    const body = ctx.createGain();
    body.gain.value = 0.34;

    src.connect(filter).connect(gain).connect(body).connect(this.master);
    src.start();
    lfo.start();
    return { src, gain, body };
  }

  makeLeaves() {
    const ctx = this.ctx;
    const src = ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    src.loop = true;
    src.playbackRate.value = 1.3;

    const hp = ctx.createBiquadFilter();
    hp.type = 'highpass';
    hp.frequency.value = 1400;

    const gain = ctx.createGain();
    gain.gain.value = 0.012;

    const lfo = ctx.createOscillator();
    lfo.frequency.value = 0.11;
    const lfoGain = ctx.createGain();
    lfoGain.gain.value = 0.008;
    lfo.connect(lfoGain).connect(gain.gain);

    src.connect(hp).connect(gain).connect(this.master);
    src.start();
    lfo.start();
    return { src, gain };
  }

  setVolume(value) {
    this.volume = Math.max(0, Math.min(1, value));
    if (!this.master || !this.ctx) return;
    const target = this.paused ? this.volume * 0.24 : this.volume;
    this.master.gain.setTargetAtTime(target * 0.75, this.ctx.currentTime, 0.25);
  }

  setPaused(paused) {
    this.paused = paused;
    this.setVolume(this.volume);
  }

  scheduleBird() {
    if (!this.started) return;
    clearTimeout(this.birdTimer);
    const delay = 3500 + Math.random() * 8000;
    this.birdTimer = setTimeout(() => {
      if (!this.paused && this.ctx?.state === 'running') this.chirp();
      this.scheduleBird();
    }, delay);
  }

  chirp() {
    const ctx = this.ctx;
    if (!ctx) return;
    const now = ctx.currentTime;
    const notes = 1 + Math.floor(Math.random() * 3);
    const base = 1750 + Math.random() * 1000;
    for (let n = 0; n < notes; n++) {
      const t = now + n * (0.09 + Math.random() * 0.08);
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      const pan = ctx.createStereoPanner ? ctx.createStereoPanner() : null;
      osc.type = Math.random() > 0.55 ? 'sine' : 'triangle';
      const startFreq = base * (0.86 + Math.random() * 0.3);
      osc.frequency.setValueAtTime(startFreq, t);
      osc.frequency.exponentialRampToValueAtTime(startFreq * (1.22 + Math.random() * 0.35), t + 0.045);
      osc.frequency.exponentialRampToValueAtTime(startFreq * 0.92, t + 0.13);
      gain.gain.setValueAtTime(0.0001, t);
      gain.gain.exponentialRampToValueAtTime(0.022 + Math.random() * 0.016, t + 0.016);
      gain.gain.exponentialRampToValueAtTime(0.0001, t + 0.16);
      if (pan) {
        pan.pan.value = Math.random() * 1.4 - 0.7;
        osc.connect(gain).connect(pan).connect(this.master);
      } else {
        osc.connect(gain).connect(this.master);
      }
      osc.start(t);
      osc.stop(t + 0.2);
    }
  }

  footstep(surface = 'duff') {
    if (!this.ctx || !this.started) return;
    const ctx = this.ctx;
    const now = ctx.currentTime;
    const src = ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    src.playbackRate.value = 0.7 + Math.random() * 0.5;

    const filter = ctx.createBiquadFilter();
    filter.type = 'bandpass';
    filter.frequency.value = surface === 'trail' ? 520 : 820;
    filter.Q.value = 0.8;

    const gain = ctx.createGain();
    gain.gain.setValueAtTime(0.0001, now);
    gain.gain.exponentialRampToValueAtTime(0.055 + Math.random() * 0.02, now + 0.012);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.12);

    src.connect(filter).connect(gain).connect(this.master);
    src.start(now, Math.random() * 2.5, 0.16);
  }

  jump() {
    if (!this.ctx || !this.started) return;
    const ctx = this.ctx;
    const now = ctx.currentTime;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = 'sine';
    osc.frequency.setValueAtTime(150, now);
    osc.frequency.exponentialRampToValueAtTime(85, now + 0.14);
    gain.gain.setValueAtTime(0.0001, now);
    gain.gain.exponentialRampToValueAtTime(0.02, now + 0.01);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.16);
    osc.connect(gain).connect(this.master);
    osc.start(now);
    osc.stop(now + 0.18);
  }

  land() {
    if (!this.ctx || !this.started) return;
    const ctx = this.ctx;
    const now = ctx.currentTime;
    const src = ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    src.playbackRate.value = 0.45;
    const filter = ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 320;
    const gain = ctx.createGain();
    gain.gain.setValueAtTime(0.0001, now);
    gain.gain.exponentialRampToValueAtTime(0.09, now + 0.012);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.2);
    src.connect(filter).connect(gain).connect(this.master);
    src.start(now, 0.2, 0.24);
  }
}

import * as THREE from '../vendor/three.module.min.js';
import { createWorld } from './world.js';
import { ForestAudio } from './audio.js';

/* ============================================================
   Silverpine Wilds — game controller
   ============================================================ */

const $ = (id) => document.getElementById(id);

const dom = {
  canvas: $('scene'),
  loading: $('loadingScreen'),
  loadingLabel: document.querySelector('.loading-label'),
  loadingNote: document.querySelector('.loading-note'),
  startScreen: $('startScreen'),
  startButton: $('startButton'),
  startSettingsButton: $('startSettingsButton'),
  hud: $('hud'),
  settingsButton: $('settingsButton'),
  potatoPill: $('potatoPill'),
  compassTrack: $('compassTrack'),
  compassReadout: $('compassReadout'),
  locationName: $('locationName'),
  walkTime: $('walkTime'),
  walkDistance: $('walkDistance'),
  crosshair: document.querySelector('.crosshair'),
  mobileControls: $('mobileControls'),
  joystick: $('joystick'),
  joystickKnob: $('joystickKnob'),
  jumpButton: $('jumpButton'),
  lookHint: $('lookHint'),
  warningModal: $('warningModal'),
  turnOnPotato: $('turnOnPotato'),
  maybeLater: $('maybeLater'),
  settingsScrim: $('settingsScrim'),
  settingsPanel: $('settingsPanel'),
  closeSettings: $('closeSettings'),
  potatoToggle: $('potatoToggle'),
  fovRange: $('fovRange'),
  fovValue: $('fovValue'),
  sensitivityRange: $('sensitivityRange'),
  sensitivityValue: $('sensitivityValue'),
  volumeRange: $('volumeRange'),
  volumeValue: $('volumeValue'),
  qualitySelect: $('qualitySelect'),
  controlsSelect: $('controlsSelect'),
  resetPosition: $('resetPosition'),
  pauseMenu: $('pauseMenu'),
  resumeButton: $('resumeButton'),
  pauseSettingsButton: $('pauseSettingsButton'),
  toast: $('toast'),
  rotateHint: $('rotateHint'),
};

const isTouchDevice = (() => {
  const coarse = window.matchMedia?.('(pointer: coarse)').matches;
  const touch = navigator.maxTouchPoints > 0;
  return Boolean(coarse || touch);
})();

const state = {
  ready: false,
  started: false,
  paused: false,
  settingsOpen: false,
  warningOpen: true,
  potato: false,
  fov: 72,
  sensitivity: 1,
  volume: 0.4,
  controlsMode: 'auto',
  isTouch: isTouchDevice,
  keys: new Set(),
  joy: { id: null, x: 0, y: 0, active: false },
  look: { id: null, x: 0, y: 0 },
  elapsed: 0,
  distance: 0,
  zone: '',
  suppressUnlock: false,
  lastHud: 0,
  lastZone: 0,
  stepAccum: 0,
  bobPhase: 0,
};

let renderer;
let scene;
let camera;
let world;
let audio;
let clock;

const player = {
  pos: new THREE.Vector3(0, 0, 0),
  vel: new THREE.Vector2(0, 0),
  yaw: 0,
  pitch: -0.03,
  vy: 0,
  onGround: true,
  bob: 0,
  landDip: 0,
  roll: 0,
  moveForward: 0,
  moveStrafe: 0,
};

let toastTimer = null;
let lookHintTimer = null;
let cinematicAngle = 0;

const CARDINALS = ['N', 'NE', 'E', 'SE', 'S', 'SW', 'W', 'NW'];
const compassItems = [];

/* ---------- formatting ---------- */

function pad(n) { return String(n).padStart(2, '0'); }

function formatTime(seconds) {
  const total = Math.floor(seconds);
  const h = Math.floor(total / 3600);
  const m = Math.floor((total % 3600) / 60);
  const s = total % 60;
  return h > 0 ? `${h}:${pad(m)}:${pad(s)}` : `${pad(m)}:${pad(s)}`;
}

function showToast(html, duration = 3400) {
  dom.toast.innerHTML = html;
  dom.toast.classList.add('show');
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => dom.toast.classList.remove('show'), duration);
}

/* ---------- renderer ---------- */

function pixelRatio() {
  const dpr = window.devicePixelRatio || 1;
  return Math.min(dpr, state.potato ? 1 : 1.7);
}

function resize() {
  if (!renderer || !camera) return;
  const w = window.innerWidth;
  const h = window.innerHeight;
  renderer.setPixelRatio(pixelRatio());
  renderer.setSize(w, h);
  camera.aspect = w / h;
  camera.updateProjectionMatrix();
  updateResponsiveHints();
}

function setupRenderer() {
  renderer = new THREE.WebGLRenderer({
    canvas: dom.canvas,
    antialias: true,
    powerPreference: 'high-performance',
  });
  renderer.outputColorSpace = THREE.SRGBColorSpace;
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.03;
  renderer.setPixelRatio(pixelRatio());
  renderer.setSize(window.innerWidth, window.innerHeight);

  scene = new THREE.Scene();
  camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.08, 460);
  camera.rotation.order = 'YXZ';
  clock = new THREE.Clock();
}

/* ---------- player ---------- */

function resetPlayer(showMessage = false) {
  player.pos.copy(world.spawn);
  player.pos.y = world.heightAt(player.pos.x, player.pos.z);
  player.vel.set(0, 0);
  player.vy = 0;
  player.onGround = true;
  player.yaw = 0;
  player.pitch = -0.035;
  player.bob = 0;
  player.landDip = 0;
  player.roll = 0;
  state.elapsed = 0;
  state.distance = 0;
  state.stepAccum = 0;
  state.zone = '';
  syncCamera();
  if (showMessage) showToast('Returned to <strong>The Clearing</strong>.');
}

function syncCamera() {
  if (!world) return;
  const eye = 1.68;
  camera.position.set(player.pos.x, player.pos.y + eye + player.bob - player.landDip, player.pos.z);
  camera.rotation.set(player.pitch, player.yaw, player.roll);
}

function tryJump() {
  if (!state.started || state.paused || state.settingsOpen || !state.ready) return;
  if (!player.onGround) return;
  player.vy = 7.35;
  player.onGround = false;
  player.landDip = 0;
  audio?.jump();
}

function getInput() {
  let forward = 0;
  let strafe = 0;
  if (state.keys.has('KeyW') || state.keys.has('ArrowUp')) forward += 1;
  if (state.keys.has('KeyS') || state.keys.has('ArrowDown')) forward -= 1;
  if (state.keys.has('KeyD') || state.keys.has('ArrowRight')) strafe += 1;
  if (state.keys.has('KeyA') || state.keys.has('ArrowLeft')) strafe -= 1;

  if (state.joy.active) {
    strafe += state.joy.x;
    forward += -state.joy.y;
  }

  const len = Math.hypot(forward, strafe);
  if (len > 1) {
    forward /= len;
    strafe /= len;
  }
  return { forward, strafe, len: Math.min(len, 1) };
}

function updatePlayer(dt) {
  const input = getInput();
  player.moveForward = input.forward;
  player.moveStrafe = input.strafe;

  const sprinting = state.keys.has('ShiftLeft') || state.keys.has('ShiftRight');
  const touchSprint = state.joy.active && Math.hypot(state.joy.x, state.joy.y) > 0.93;
  const maxSpeed = sprinting ? 7.5 : touchSprint ? 5.9 : 4.35;

  const sin = Math.sin(player.yaw);
  const cos = Math.cos(player.yaw);
  const fwdX = -sin;
  const fwdZ = -cos;
  const rightX = cos;
  const rightZ = -sin;

  const targetX = (fwdX * input.forward + rightX * input.strafe) * maxSpeed;
  const targetZ = (fwdZ * input.forward + rightZ * input.strafe) * maxSpeed;
  const accel = player.onGround ? 13 : 3.2;
  const blend = 1 - Math.exp(-accel * dt);
  player.vel.x += (targetX - player.vel.x) * blend;
  player.vel.y += (targetZ - player.vel.y) * blend;

  const beforeX = player.pos.x;
  const beforeZ = player.pos.z;
  const nextX = player.pos.x + player.vel.x * dt;
  const nextZ = player.pos.z + player.vel.y * dt;
  const solved = world.resolveCollision(nextX, nextZ, 0.36);
  player.pos.x = solved.x;
  player.pos.z = solved.z;

  const moved = Math.hypot(player.pos.x - beforeX, player.pos.z - beforeZ);
  state.distance += moved;

  // Vertical motion and the forest floor.
  const ground = world.heightAt(player.pos.x, player.pos.z);
  if (player.onGround) {
    if (ground < player.pos.y - 0.62) {
      player.onGround = false;
    } else {
      player.pos.y = ground;
      player.vy = 0;
    }
  }
  if (!player.onGround) {
    player.vy -= 21.5 * dt;
    player.pos.y += player.vy * dt;
    if (player.pos.y <= ground) {
      const impact = player.vy;
      player.pos.y = ground;
      player.vy = 0;
      player.onGround = true;
      if (impact < -4.5) {
        player.landDip = Math.min(0.13, -impact * 0.012);
        audio?.land();
      }
    }
  }

  // Head bob and footsteps.
  const speed = Math.hypot(player.vel.x, player.vel.y);
  if (player.onGround && speed > 0.25) {
    player.bobPhase += dt * (6.3 + speed * 0.85);
    player.bob = Math.sin(player.bobPhase * 2) * 0.032 * Math.min(1, speed / 4.2);
    state.stepAccum += moved;
    if (state.stepAccum > 2.05) {
      state.stepAccum = 0;
      const surface = world.pathDistance(player.pos.x, player.pos.z) < 3.1 ? 'trail' : 'duff';
      audio?.footstep(surface);
    }
  } else {
    player.bob += (0 - player.bob) * (1 - Math.exp(-8 * dt));
  }

  player.landDip *= Math.exp(-9 * dt);
  player.roll += (-input.strafe * 0.009 - player.roll) * (1 - Math.exp(-7 * dt));

  state.elapsed += dt;

  // Camera follows the body with a gentle eye height.
  const eye = 1.68;
  camera.position.set(
    player.pos.x,
    player.pos.y + eye + player.bob - player.landDip,
    player.pos.z
  );
  camera.rotation.set(player.pitch, player.yaw, player.roll);

  const portrait = window.innerHeight > window.innerWidth ? 6 : 0;
  const sprintFov = speed > 5.4 ? 3 : 0;
  const targetFov = state.fov + portrait + sprintFov;
  if (Math.abs(camera.fov - targetFov) > 0.03) {
    camera.fov += (targetFov - camera.fov) * (1 - Math.exp(-6 * dt));
    camera.updateProjectionMatrix();
  }
}

function updateCinematic(t) {
  const angle = 0.34 + Math.sin(t * 0.035) * 0.14;
  const x = 8.4 + Math.sin(angle) * 1.5;
  const z = 16.8 + Math.cos(angle) * 0.9;
  const y = world.heightAt(x, z) + 4.35 + Math.sin(t * 0.24) * 0.09;
  camera.position.set(x, y, z);
  const lookX = -1.2;
  const lookZ = -19;
  const lookY = world.heightAt(lookX, lookZ) + 2.5;
  camera.lookAt(lookX, lookY, lookZ);
  camera.rotation.z = 0;
  if (Math.abs(camera.fov - 61) > 0.1) {
    camera.fov += (61 - camera.fov) * 0.08;
    camera.updateProjectionMatrix();
  }
}

/* ---------- compass + HUD ---------- */

function buildCompass() {
  const names = { 0: 'N', 45: 'NE', 90: 'E', 135: 'SE', 180: 'S', 225: 'SW', 270: 'W', 315: 'NW' };
  for (let deg = 0; deg < 360; deg += 15) {
    const tick = document.createElement('span');
    tick.className = 'compass-tick' + (deg % 45 === 0 ? ' major' : '');
    tick.style.position = 'absolute';
    tick.style.left = '50%';
    dom.compassTrack.appendChild(tick);
    compassItems.push({ el: tick, deg, offset: 0 });

    if (names[deg] !== undefined) {
      const label = document.createElement('span');
      label.className = 'compass-label' + (deg % 90 === 0 ? ' cardinal' : '');
      label.textContent = names[deg];
      label.style.position = 'absolute';
      label.style.left = '50%';
      dom.compassTrack.appendChild(label);
      compassItems.push({ el: label, deg, offset: 0 });
    }
  }
}

function updateCompass() {
  const heading = ((-player.yaw * 180) / Math.PI % 360 + 360) % 360;
  for (const item of compassItems) {
    let d = item.deg - heading;
    while (d > 180) d -= 360;
    while (d < -180) d += 360;
    const offset = d * 2.05;
    item.el.style.transform = `translateX(calc(-50% + ${offset.toFixed(1)}px))`;
    item.el.style.opacity = Math.abs(offset) > 98 ? '0' : String(1 - Math.abs(offset) / 115);
  }
  const cardinal = CARDINALS[Math.round(heading / 45) % 8];
  dom.compassReadout.textContent = `${cardinal} · ${String(Math.round(heading)).padStart(3, '0')}°`;
}

function zoneName() {
  if (!world) return 'Silverpine Wilds';
  let best = null;
  let bestScore = Infinity;
  for (const landmark of world.landmarks) {
    const d = Math.hypot(player.pos.x - landmark.x, player.pos.z - landmark.z);
    if (d < landmark.r) {
      const score = d / landmark.r;
      if (score < bestScore) { bestScore = score; best = landmark; }
    }
  }
  return best ? best.name : 'Silverpine Wilds';
}

function updateHud(now) {
  if (now - state.lastHud < 0.15) return;
  state.lastHud = now;
  dom.walkTime.textContent = formatTime(state.elapsed);
  dom.walkDistance.textContent = `${Math.floor(state.distance)} m`;
  if (now - state.lastZone > 0.45) {
    state.lastZone = now;
    const zone = zoneName();
    if (zone !== state.zone) {
      state.zone = zone;
      dom.locationName.textContent = zone;
    }
  }
  updateCompass();
}

/* ---------- quality / settings ---------- */

function updateQualityUI() {
  dom.potatoToggle.setAttribute('aria-checked', String(state.potato));
  dom.potatoPill.classList.toggle('is-hidden', !state.potato);
  dom.qualitySelect.value = state.potato ? 'potato' : 'high';
  document.body.classList.toggle('potato-mode', state.potato);
}

function setPotato(on, { silent = false, pulse = false } = {}) {
  state.potato = Boolean(on);
  if (world) world.setPotato(state.potato);
  updateQualityUI();
  if (renderer && camera) resize();
  if (!silent) {
    showToast(state.potato
      ? '<strong>Potato Mode on.</strong> Dense grass, mist and shadows are off.'
      : '<strong>High graphics restored.</strong> The full forest is back.');
  }
  if (pulse) {
    dom.potatoToggle.classList.remove('pulse');
    void dom.potatoToggle.offsetWidth;
    dom.potatoToggle.classList.add('pulse');
    setTimeout(() => dom.potatoToggle.classList.remove('pulse'), 1500);
  }
  window.__potatoMode = state.potato;
}

function sensitivityLabel(value) {
  if (value < 55) return 'Low';
  if (value < 95) return 'Normal';
  if (value < 140) return 'High';
  return 'Very high';
}

function updateVolumeUI() {
  dom.volumeValue.textContent = `${Math.round(state.volume * 100)}%`;
}

/* ---------- overlays ---------- */

function dismissWarning() {
  if (!state.warningOpen) return;
  state.warningOpen = false;
  dom.warningModal.classList.add('is-hidden');
  setTimeout(() => dom.startButton.focus({ preventScroll: true }), 50);
}

function openSettings(options = {}) {
  if (!state.ready || state.settingsOpen) return;
  state.settingsOpen = true;
  dom.pauseMenu.classList.add('is-hidden');
  dom.settingsPanel.classList.remove('is-hidden');
  dom.settingsScrim.classList.remove('is-hidden');
  updateQualityUI();
  audio?.setPaused(true);
  if (document.pointerLockElement) {
    state.suppressUnlock = true;
    document.exitPointerLock?.();
    setTimeout(() => { state.suppressUnlock = false; }, 400);
  }
  refreshTouchControls();
  setTimeout(() => {
    const first = options.focusPotato ? dom.potatoToggle : dom.closeSettings;
    first?.focus({ preventScroll: true });
    if (options.focusPotato) {
      dom.potatoToggle.classList.remove('pulse');
      void dom.potatoToggle.offsetWidth;
      dom.potatoToggle.classList.add('pulse');
      setTimeout(() => dom.potatoToggle.classList.remove('pulse'), 1500);
    }
  }, 250);
}

function closeSettings() {
  if (!state.settingsOpen) return;
  state.settingsOpen = false;
  dom.settingsPanel.classList.add('is-hidden');
  dom.settingsScrim.classList.add('is-hidden');
  audio?.setPaused(state.paused);
  if (state.started) {
    if (state.paused) {
      dom.pauseMenu.classList.remove('is-hidden');
    } else {
      requestLock();
    }
  }
  refreshTouchControls();
  if (state.started) setTimeout(() => dom.canvas.focus?.({ preventScroll: true }), 30);
}

function pauseGame() {
  if (!state.started || state.paused) return;
  state.paused = true;
  if (state.settingsOpen) closeSettings();
  dom.pauseMenu.classList.remove('is-hidden');
  refreshTouchControls();
  audio?.setPaused(true);
  if (document.pointerLockElement) {
    state.suppressUnlock = true;
    document.exitPointerLock?.();
    setTimeout(() => { state.suppressUnlock = false; }, 400);
  }
}

function resumeGame() {
  if (!state.started) return;
  state.paused = false;
  dom.pauseMenu.classList.add('is-hidden');
  dom.settingsPanel.classList.add('is-hidden');
  dom.settingsScrim.classList.add('is-hidden');
  state.settingsOpen = false;
  refreshTouchControls();
  audio?.setPaused(false);
  requestLock();
  dom.canvas.focus?.({ preventScroll: true });
}

function requestLock() {
  if (state.isTouch) return;
  try {
    const promise = dom.canvas.requestPointerLock?.();
    if (promise && typeof promise.catch === 'function') promise.catch(() => {});
  } catch { /* pointer lock is a nice-to-have */ }
}

/* ---------- start / touch controls ---------- */

function showTouchControls() {
  if (state.controlsMode === 'on') return true;
  if (state.controlsMode === 'off') return false;
  return state.isTouch;
}

function refreshTouchControls() {
  const visible = state.started && !state.paused && !state.settingsOpen && showTouchControls();
  dom.mobileControls.classList.toggle('is-hidden', !visible);
  dom.crosshair.style.display = (state.isTouch || showTouchControls()) ? 'none' : '';
}

function startGame() {
  if (!state.started && state.ready) {
    state.started = true;
    if (state.warningOpen) dismissWarning();
    state.paused = false;
    state.elapsed = 0;
    state.distance = 0;
    player.pos.copy(world.spawn);
    player.pos.y = world.heightAt(player.pos.x, player.pos.z);
    player.yaw = 0;
    player.pitch = -0.035;
    syncCamera();
    dom.startScreen.classList.add('fade-out');
    setTimeout(() => dom.startScreen.classList.add('is-hidden'), 1050);
    dom.hud.classList.remove('is-hidden');
    document.body.classList.add('is-playing');
    refreshTouchControls();
    requestLock();
    audio?.start();
    audio?.setPaused(false);
    if (state.isTouch) {
      clearTimeout(lookHintTimer);
      dom.lookHint.classList.remove('fade');
      lookHintTimer = setTimeout(() => dom.lookHint.classList.add('fade'), 5200);
    }
    dom.canvas.tabIndex = -1;
    dom.canvas.focus({ preventScroll: true });
  }
}

/* ---------- input ---------- */

function onKeyDown(e) {
  const tag = e.target?.tagName;
  const inForm = tag === 'INPUT' || tag === 'SELECT' || tag === 'TEXTAREA' || tag === 'BUTTON';

  if (e.code === 'Escape') {
    if (state.warningOpen && !state.started) {
      e.preventDefault();
      setPotato(true);
      dismissWarning();
      showToast('<strong>Potato Mode on.</strong> Press Esc again any time for Settings.');
      return;
    }
    if (state.settingsOpen) {
      e.preventDefault();
      closeSettings();
      return;
    }
    if (state.paused) {
      e.preventDefault();
      resumeGame();
      return;
    }
    if (state.started) {
      e.preventDefault();
      pauseGame();
      return;
    }
  }

  if (inForm) return;

  if (e.code === 'KeyP') {
    if (state.ready) {
      e.preventDefault();
      setPotato(!state.potato, { pulse: true });
    }
    return;
  }

  if (!state.started || state.paused || state.settingsOpen) return;

  if (e.code === 'Space') {
    e.preventDefault();
    if (!e.repeat) tryJump();
    return;
  }

  if (e.code === 'KeyW' || e.code === 'KeyA' || e.code === 'KeyS' || e.code === 'KeyD' ||
      e.code === 'ArrowUp' || e.code === 'ArrowDown' || e.code === 'ArrowLeft' || e.code === 'ArrowRight' ||
      e.code === 'ShiftLeft' || e.code === 'ShiftRight') {
    e.preventDefault();
    state.keys.add(e.code);
  }
}

function onKeyUp(e) {
  state.keys.delete(e.code);
}

function setupJoystick() {
  const maxRadius = () => dom.joystick.clientWidth * 0.31;

  function update(e) {
    const rect = dom.joystick.getBoundingClientRect();
    const cx = rect.left + rect.width / 2;
    const cy = rect.top + rect.height / 2;
    let dx = e.clientX - cx;
    let dy = e.clientY - cy;
    const max = maxRadius();
    const dist = Math.hypot(dx, dy);
    if (dist > max) {
      dx = (dx / dist) * max;
      dy = (dy / dist) * max;
    }
    state.joy.x = dx / max;
    state.joy.y = dy / max;
    dom.joystickKnob.style.transform = `translate(calc(-50% + ${dx.toFixed(1)}px), calc(-50% + ${dy.toFixed(1)}px))`;
  }

  dom.joystick.addEventListener('pointerdown', (e) => {
    if (!state.started || state.paused || state.settingsOpen) return;
    e.preventDefault();
    state.joy.id = e.pointerId;
    state.joy.active = true;
    dom.joystick.classList.add('active');
    dom.joystick.setPointerCapture?.(e.pointerId);
    update(e);
  });

  dom.joystick.addEventListener('pointermove', (e) => {
    if (state.joy.id !== e.pointerId) return;
    update(e);
  });

  const end = (e) => {
    if (state.joy.id !== e.pointerId) return;
    state.joy.id = null;
    state.joy.active = false;
    state.joy.x = 0;
    state.joy.y = 0;
    dom.joystick.classList.remove('active');
    dom.joystickKnob.style.transform = 'translate(-50%, -50%)';
  };
  dom.joystick.addEventListener('pointerup', end);
  dom.joystick.addEventListener('pointercancel', end);
  dom.joystick.addEventListener('lostpointercapture', end);

  dom.jumpButton.addEventListener('pointerdown', (e) => {
    if (!state.started || state.paused || state.settingsOpen) return;
    e.preventDefault();
    dom.jumpButton.classList.add('pressed');
    dom.jumpButton.setPointerCapture?.(e.pointerId);
    tryJump();
  });
  const unpress = () => dom.jumpButton.classList.remove('pressed');
  dom.jumpButton.addEventListener('pointerup', unpress);
  dom.jumpButton.addEventListener('pointercancel', unpress);
  dom.jumpButton.addEventListener('pointerleave', unpress);
}

function setupTouchLook() {
  dom.canvas.addEventListener('pointerdown', (e) => {
    if (e.pointerType === 'mouse') {
      if (state.started && !state.paused && !state.settingsOpen && document.pointerLockElement !== dom.canvas) {
        requestLock();
      }
      return;
    }
    if (!state.started || state.paused || state.settingsOpen) return;
    e.preventDefault();
    state.look.id = e.pointerId;
    state.look.x = e.clientX;
    state.look.y = e.clientY;
    dom.canvas.setPointerCapture?.(e.pointerId);
    document.body.classList.add('is-looking');
  });

  dom.canvas.addEventListener('pointermove', (e) => {
    if (state.look.id !== e.pointerId) return;
    const dx = e.clientX - state.look.x;
    const dy = e.clientY - state.look.y;
    state.look.x = e.clientX;
    state.look.y = e.clientY;
    const sens = 0.0042 * state.sensitivity;
    player.yaw -= dx * sens;
    player.pitch = Math.max(-1.34, Math.min(1.34, player.pitch - dy * sens));
  });

  const endLook = (e) => {
    if (state.look.id !== e.pointerId) return;
    state.look.id = null;
    document.body.classList.remove('is-looking');
  };
  dom.canvas.addEventListener('pointerup', endLook);
  dom.canvas.addEventListener('pointercancel', endLook);
  dom.canvas.addEventListener('lostpointercapture', endLook);
}

function setupPointerLock() {
  document.addEventListener('pointerlockchange', () => {
    const locked = document.pointerLockElement === dom.canvas;
    document.body.classList.toggle('is-looking', locked);
    if (locked) {
      if (state.paused && !state.settingsOpen) {
        state.paused = false;
        dom.pauseMenu.classList.add('is-hidden');
        audio?.setPaused(false);
        refreshTouchControls();
      }
      return;
    }
    if (state.started && !state.paused && !state.settingsOpen && !state.suppressUnlock && !state.isTouch) {
      pauseGame();
    }
  });

  document.addEventListener('pointerlockerror', () => {
    if (state.started) showToast('Click the forest to capture the mouse and look around.', 2800);
  });

  document.addEventListener('mousemove', (e) => {
    if (document.pointerLockElement !== dom.canvas) return;
    if (!state.started || state.paused || state.settingsOpen) return;
    const sens = 0.0022 * state.sensitivity;
    player.yaw -= (e.movementX || 0) * sens;
    player.pitch = Math.max(-1.34, Math.min(1.34, player.pitch - (e.movementY || 0) * sens));
  });
}

/* ---------- UI wiring ---------- */

function setupUI() {
  buildCompass();

  dom.startButton.addEventListener('click', startGame);
  dom.startSettingsButton.addEventListener('click', () => openSettings());
  dom.settingsButton.addEventListener('click', () => openSettings());
  dom.pauseSettingsButton.addEventListener('click', () => openSettings());
  dom.closeSettings.addEventListener('click', closeSettings);
  dom.settingsScrim.addEventListener('click', closeSettings);
  dom.resumeButton.addEventListener('click', resumeGame);

  dom.turnOnPotato.addEventListener('click', () => {
    setPotato(true);
    dismissWarning();
  });
  dom.maybeLater.addEventListener('click', dismissWarning);

  dom.potatoToggle.addEventListener('click', () => setPotato(!state.potato, { pulse: true }));
  dom.qualitySelect.addEventListener('change', () => setPotato(dom.qualitySelect.value === 'potato'));

  dom.fovRange.addEventListener('input', () => {
    state.fov = Number(dom.fovRange.value);
    dom.fovValue.textContent = `${state.fov}°`;
  });
  dom.sensitivityRange.addEventListener('input', () => {
    state.sensitivity = Number(dom.sensitivityRange.value) / 100;
    dom.sensitivityValue.textContent = sensitivityLabel(Number(dom.sensitivityRange.value));
  });
  dom.volumeRange.addEventListener('input', () => {
    state.volume = Number(dom.volumeRange.value) / 100;
    updateVolumeUI();
    audio?.setVolume(state.volume);
  });
  dom.controlsSelect.addEventListener('change', () => {
    state.controlsMode = dom.controlsSelect.value;
    refreshTouchControls();
  });
  dom.resetPosition.addEventListener('click', () => resetPlayer(true));

  dom.settingsScrim.classList.add('is-hidden');
  dom.settingsPanel.classList.add('is-hidden');

  document.addEventListener('keydown', onKeyDown);
  document.addEventListener('keyup', onKeyUp);
  document.addEventListener('visibilitychange', () => {
    if (document.hidden && state.started && !state.paused) pauseGame();
  });
  window.addEventListener('resize', resize);
  window.addEventListener('orientationchange', () => setTimeout(() => { resize(); updateResponsiveHints(); }, 120));
  window.addEventListener('blur', () => state.keys.clear());

  dom.canvas.addEventListener('contextmenu', (e) => e.preventDefault());
  dom.canvas.addEventListener('touchmove', (e) => e.preventDefault(), { passive: false });
  document.addEventListener('gesturestart', (e) => e.preventDefault());

  // State that comes from persisted-ish defaults.
  dom.fovValue.textContent = `${state.fov}°`;
  dom.sensitivityValue.textContent = sensitivityLabel(100);
  updateVolumeUI();
  updateQualityUI();
  document.body.classList.toggle('touch-device', state.isTouch);
}

function updateResponsiveHints() {
  const portrait = window.innerHeight > window.innerWidth;
  const show = state.started && state.isTouch && portrait && window.innerWidth < 600;
  dom.rotateHint.classList.toggle('is-hidden', !show);
  if (show) {
    clearTimeout(updateResponsiveHints.timer);
    updateResponsiveHints.timer = setTimeout(() => dom.rotateHint.classList.add('is-hidden'), 4200);
  }
}

/* ---------- boot / loop ---------- */

async function boot() {
  setupUI();
  try {
    setupRenderer();
    // Let the loading screen paint before the synchronous forest generation.
    await new Promise((resolve) => requestAnimationFrame(() => requestAnimationFrame(resolve)));
    world = createWorld(scene, renderer);
    audio = new ForestAudio();
    audio.setVolume(state.volume);
    resetPlayer(false);
    updateCinematic(0);
    updateQualityUI();
    state.ready = true;

    dom.loading.classList.add('done');
    setTimeout(() => dom.loading.classList.add('is-hidden'), 950);
    dom.startScreen.classList.remove('is-hidden');
    dom.warningModal.classList.remove('is-hidden');

    window.__forestReady = true;
    window.__silverpine = {
      start: startGame,
      reset: () => resetPlayer(false),
      setPotato,
      dismissWarning,
      state,
      player,
      get world() { return world; },
      get camera() { return camera; },
      get renderer() { return renderer; },
    };

    clock.start();
    animate();
  } catch (error) {
    console.error(error);
    dom.loadingLabel.textContent = 'The forest could not grow';
    dom.loadingNote.textContent = 'Your browser may not support WebGL. Try a current version of Chrome, Edge or Safari.';
    dom.loading.classList.remove('done');
  }
}

function animate() {
  requestAnimationFrame(animate);
  if (!world) return;

  const dt = Math.min(clock.getDelta(), 0.05);
  const t = clock.elapsedTime;

  if (state.started) {
    if (!state.paused && !state.settingsOpen) updatePlayer(dt);
    else {
      syncCamera();
      const targetFov = state.fov + (window.innerHeight > window.innerWidth ? 6 : 0);
      if (Math.abs(camera.fov - targetFov) > 0.05) {
        camera.fov += (targetFov - camera.fov) * 0.1;
        camera.updateProjectionMatrix();
      }
    }
    updateHud(t);
  } else {
    updateCinematic(t);
  }

  world.update(t, dt, camera.position);
  renderer.render(scene, camera);
}

boot();

