const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
const fs = require('fs');

(async () => {
  const browser = await chromium.launch({
    headless: false,
    args: ['--enable-gpu', '--ignore-gpu-blocklist', '--use-angle=vulkan', '--use-vulkan=swiftshader', '--disable-vulkan-surface'],
  });
  const errors = [];
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  page.on('console', msg => { if (msg.type() === 'error') { console.log('CONSOLE ERROR:', msg.text()); errors.push(msg.text()); } });
  page.on('pageerror', err => { console.log('PAGE ERROR:', err.message); errors.push(err.message); });
  const t0 = Date.now();
  await page.goto('http://localhost:3002/', { waitUntil: 'load', timeout: 60000 });
  await page.waitForFunction(() => window.__forestReady === true, null, { timeout: 90000 });
  console.log('Ready in', Date.now() - t0, 'ms');
  await page.waitForTimeout(1800);
  await page.screenshot({ path: 'screenshots/01-warning.png' });

  const warningVisible = await page.locator('#warningModal').isVisible();
  console.log('warning visible:', warningVisible);
  console.log('buttons:', await page.locator('#turnOnPotato').innerText(), '/', await page.locator('#maybeLater').innerText());

  await page.getByRole('button', { name: 'Maybe Later' }).click();
  await page.waitForTimeout(900);
  await page.screenshot({ path: 'screenshots/02-start.png' });

  await page.getByRole('button', { name: /Start Exploring/ }).click();
  await page.waitForTimeout(2200);
  await page.screenshot({ path: 'screenshots/03-play.png' });

  // Walk forward a bit and look around.
  await page.mouse.move(720, 450);
  await page.waitForTimeout(300);
  await page.keyboard.down('KeyW');
  await page.waitForTimeout(2600);
  await page.keyboard.up('KeyW');
  await page.keyboard.press('Space');
  await page.waitForTimeout(900);
  await page.screenshot({ path: 'screenshots/04-walk.png' });

  // Open settings through the top-right gear.
  await page.keyboard.press('Escape');
  await page.waitForTimeout(1200);
