  ? vary(rng, 0xbdb9a2, 0xdedac4, rng())
  : vary(rng, 0x514335, 0x7b684e, rng()).multiplyScalar(0.86 + rng() * 0.22);
trunks.push({
  matrix: matrixAt(x, y + h / 2, z, radius, h, radius, rotY),
  color: trunkColor,
});

const autumn = rng() < 0.12;
const centralColor = autumn
  ? vary(rng, pick(rng, AUTUMN), pick(rng, AUTUMN), rng())
  : vary(rng, pick(rng, LEAF_GREENS), pick(rng, LEAF_GREENS), rng());
centralColor.multiplyScalar(0.92 + rng() * 0.16);
const centralSize = h * (0.22 + rng() * 0.055);
leavesDetail.push({
  matrix: matrixAt(x, y + h * 0.9, z, centralSize, centralSize * (0.88 + rng() * 0.16), centralSize, rng() * 6),
  color: centralColor,
});

const blobs = 6 + Math.floor(rng() * 4);
for (let i = 0; i < blobs; i++) {
  const a = (i / blobs) * Math.PI * 2 + rng() * 0.8;
  const spread = h * (0.14 + rng() * 0.14);
  const bx = x + Math.cos(a) * spread;
  const bz = z + Math.sin(a) * spread;
  const by = y + h * (0.78 + rng() * 0.25);
  const s = h * (0.115 + rng() * 0.075);
