/* ---------- sky ---------- */
const skyUniforms = {
  uTop: { value: new THREE.Color(0x648fa6) },
  uHorizon: { value: new THREE.Color(0xf2d5a2) },
  uSunColor: { value: new THREE.Color(0xffd28a) },
  uSun: { value: SUN_DIR.clone() },
  uTime: { value: 0 },
  uCloud: { value: 1 },
};
const skyGeometry = new THREE.SphereGeometry(430, 32, 18);
const skyMaterial = new THREE.ShaderMaterial({
  uniforms: skyUniforms,
  side: THREE.BackSide,
  depthWrite: false,
  fog: false,
  toneMapped: false,
  vertexShader: `
    varying vec3 vWorldPosition;
    void main() {
      vWorldPosition = (modelMatrix * vec4(position, 1.0)).xyz;
      gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
    }
  `,
  fragmentShader: `
    uniform vec3 uTop;
    uniform vec3 uHorizon;
    uniform vec3 uSunColor;
    uniform vec3 uSun;
    uniform float uTime;
    uniform float uCloud;
    varying vec3 vWorldPosition;

    float hash21(vec2 p) {
      p = fract(p * vec2(123.34, 456.21));
      p += dot(p, p + 45.32);
      return fract(p.x * p.y);
    }
    float vnoise(vec2 p) {
      vec2 i = floor(p);
      vec2 f = fract(p);
      f = f * f * (3.0 - 2.0 * f);
      float a = hash21(i);
      float b = hash21(i + vec2(1.0, 0.0));
      float c = hash21(i + vec2(0.0, 1.0));
      float d = hash21(i + vec2(1.0, 1.0));
      return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
    }
    float cloudNoise(vec2 p) {
      float v = 0.0;
      float a = 0.58;
      for (int i = 0; i < 3; i++) {
        v += vnoise(p) * a;
        p = p * 2.03 + vec2(11.1, 6.7);
        a *= 0.5;
      }
      return v;
    }

    void main() {
      vec3 dir = normalize(vWorldPosition - cameraPosition);
      float h = clamp(dir.y, 0.0, 1.0);
      vec3 col = mix(uHorizon, uTop, pow(h, 0.48));

      float sd = max(dot(dir, uSun), 0.0);
      col += uSunColor * (pow(sd, 760.0) * 1.9 + pow(sd, 10.0) * 0.2);
      col += uSunColor * pow(max(1.0 - h, 0.0), 4.0) * 0.05;

      if (dir.y > 0.01) {
        vec2 sp = dir.xz / (dir.y + 0.2);
        vec2 uv = sp * 0.9 + vec2(uTime * 0.002, uTime * 0.0007);
        float n = cloudNoise(uv * 1.15);
        float cloud = smoothstep(0.5, 0.78, n) * smoothstep(0.0, 0.3, dir.y) * uCloud;
        vec3 cloudCol = mix(vec3(0.46, 0.44, 0.38), vec3(0.86, 0.77, 0.57), pow(sd, 2.0));
        col = mix(col, cloudCol, cloud * 0.55);
      }

      col = mix(col, uHorizon, smoothstep(0.08, -0.04, dir.y) * 0.4);
      gl_FragColor = vec4(col, 1.0);
      #include <colorspace_fragment>
    }
  `,
});

