const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async () => {
  const browser = await chromium.launch({ headless: false, args: ['--enable-gpu','--ignore-gpu-blocklist','--use-angle=vulkan','--use-vulkan=swiftshader','--disable-vulkan-surface'] });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  const errors = [];
  page.on('pageerror', e => { console.log('PAGEERR', e.message); errors.push(e.message); });
  page.on('console', m => { if (m.type() === 'error') { console.log('CONSOLE', m.text()); errors.push(m.text()); } });
  const t0 = Date.now();
  await page.goto('http://localhost:3002/', { waitUntil: 'load', timeout: 60000 });
  await page.waitForFunction(() => window.__forestReady === true, null, { timeout: 120000 });
  console.log('ready ms', Date.now()-t0);
  await page.waitForTimeout(1600);
  await page.screenshot({ path: 'screenshots/11-warning.png' });
  await page.getByRole('button', { name: 'Maybe Later' }).click();
  await page.waitForTimeout(900);
  await page.screenshot({ path: 'screenshots/12-start.png' });
  await page.getByRole('button', { name: /Start Exploring/ }).click();
  await page.waitForTimeout(2200);
  await page.screenshot({ path: 'screenshots/13-play.png' });
  const before = await page.evaluate(() => ({elapsed: window.__silverpine.state.elapsed, dist: window.__silverpine.state.distance, frames: window.__silverpine.renderer.info.render.frame}));
  await page.keyboard.down('KeyW');
  await page.waitForTimeout(3000);
  await page.keyboard.up('KeyW');
  const after = await page.evaluate(() => ({elapsed: window.__silverpine.state.elapsed, dist: window.__silverpine.state.distance, frames: window.__silverpine.renderer.info.render.frame, pos: window.__silverpine.player.pos.toArray()}));
  console.log('walk', before, after);
  await page.screenshot({ path: 'screenshots/14-walk.png' });
  await page.keyboard.press('Escape');
  await page.waitForTimeout(800);
  await page.screenshot({ path: 'screenshots/15-pause.png' });
  await page.getByRole('button', { name: 'Settings' }).last().click().catch(async () => { await page.locator('#pauseSettingsButton').click(); });
  await page.waitForTimeout(800);
  await page.screenshot({ path: 'screenshots/16-settings.png' });
  await page.locator('#potatoToggle').click();
  await page.waitForTimeout(900);
  await page.screenshot({ path: 'screenshots/17-potato-settings.png' });
  await page.locator('#closeSettings').click();
  await page.waitForTimeout(900);
  await page.screenshot({ path: 'screenshots/18-potato-pause.png' });

  const mobile = await browser.newPage({ viewport: { width: 390, height: 844 }, hasTouch: true, isMobile: true, deviceScaleFactor: 2 });
  mobile.on('pageerror', e => console.log('MOBILE PAGEERR', e.message));
  await mobile.goto('http://localhost:3002/', { waitUntil: 'load', timeout: 60000 });
  await mobile.waitForFunction(() => window.__forestReady === true, null, { timeout: 120000 });
  await mobile.waitForTimeout(1200);
  await mobile.screenshot({ path: 'screenshots/19-mobile-warning.png' });
  await mobile.getByRole('button', { name: 'Maybe Later' }).click();
  await mobile.waitForTimeout(800);
  await mobile.screenshot({ path: 'screenshots/20-mobile-start.png' });
  await mobile.getByRole('button', { name: /Start Exploring/ }).click();
  await mobile.waitForTimeout(2300);
  await mobile.screenshot({ path: 'screenshots/21-mobile-play.png' });
  const mstate = await mobile.evaluate(() => ({touch: window.__silverpine.state.isTouch, mobileControls: !document.getElementById('mobileControls').classList.contains('is-hidden'), elapsed: window.__silverpine.state.elapsed}));
  console.log('mobile', mstate);
  console.log('errors', errors);
  await browser.close();
})();

