  await page.waitForTimeout(1800);
  await page.screenshot({ path: 'screenshots/23-play.png' });
  await page.keyboard.down('KeyW');
  await page.waitForTimeout(2500);
  await page.keyboard.up('KeyW');
  await page.waitForTimeout(300);
  await page.screenshot({ path: 'screenshots/24-walk.png' });
  await page.keyboard.press('Escape');
  await page.waitForTimeout(700);
  await page.screenshot({ path: 'screenshots/25-pause.png' });
  console.log('state', await page.evaluate(() => ({elapsed: window.__silverpine.state.elapsed, pos: window.__silverpine.player.pos.toArray(), pitch: window.__silverpine.player.pitch, yaw: window.__silverpine.player.yaw})));

  const mobile = await browser.newPage({ viewport: { width: 390, height: 844 }, hasTouch: true, isMobile: true, deviceScaleFactor: 2 });
  mobile.on('pageerror', e => console.log('MOBILE PAGEERR', e.message));
  await mobile.goto('http://localhost:3002/', { waitUntil: 'load', timeout: 60000 });
  await mobile.waitForFunction(() => window.__forestReady === true, null, { timeout: 120000 });
  await mobile.getByRole('button', { name: 'Maybe Later' }).click();
  await mobile.waitForTimeout(1200);
  await mobile.screenshot({ path: 'screenshots/26-mobile-start.png' });
  await mobile.getByRole('button', { name: /Start Exploring/ }).click();
  await mobile.waitForTimeout(1600);
  await mobile.screenshot({ path: 'screenshots/27-mobile-play.png' });
  await browser.close();
})();

