const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async () => {
  const browser = await chromium.launch({ headless: false, args: ['--enable-gpu','--ignore-gpu-blocklist'] });
  const page = await browser.newPage({ viewport: { width: 960, height: 600 } });
  page.on('pageerror', e => console.log('PAGEERR', e.message));
  page.on('console', m => { if (m.type() === 'error') console.log('CONSOLE', m.text()); });
  await page.goto('http://localhost:3002/', { waitUntil: 'load', timeout: 60000 });
  await page.waitForFunction(() => window.__forestReady === true, null, { timeout: 120000 });
  await page.getByRole('button', { name: 'Maybe Later' }).click();
  await page.getByRole('button', { name: /Start Exploring/ }).click();
  await page.waitForTimeout(600);
  const info = async (label) => {
    const data = await page.evaluate(() => {
      const s = window.__silverpine;
      const c = s.camera;
      return {
        pos: s.player.pos.toArray(),
        y: s.player.pos.y,
        bob: s.player.bob,
        camPos: c.position.toArray(),
        camRot: [c.rotation.x, c.rotation.y, c.rotation.z],
        fov: c.fov,
        near: c.near,
        far: c.far,
        matrix: c.matrixWorld.elements.slice(0, 4),
        renderCalls: s.renderer.info.render.calls,
        triangles: s.renderer.info.render.triangles,
        size: s.renderer.getSize(new (Object.getPrototypeOf(c.position).constructor)()),
        pixelRatio: s.renderer.getPixelRatio(),
        fog: s.world && s.world.sky ? 'skyok' : 'n/a',
      };
    });
    console.log(label, JSON.stringify(data));
  };
  await info('before');
  await page.screenshot({ path: '/tmp/opencode/dbg0.png' });
  await page.keyboard.down('KeyW');
  for (let i = 0; i < 5; i++) {
    await page.waitForTimeout(500);
    await info('w' + i);
    await page.screenshot({ path: `/tmp/opencode/dbg${i + 1}.png` });
  }
  await page.keyboard.up('KeyW');
  await browser.close();
})();

