const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async () => {
  const browser = await chromium.launch({ headless: false, args: ['--enable-gpu','--ignore-gpu-blocklist'] });
  const page = await browser.newPage({ viewport: { width: 390, height: 844 }, hasTouch: true, isMobile: true, deviceScaleFactor: 2 });
  const errors = [];
  page.on('pageerror', e => errors.push('PAGEERR ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });
  await page.goto('http://localhost:3002/', { waitUntil: 'load', timeout: 60000 });
  await page.waitForFunction(() => window.__forestReady === true, null, { timeout: 120000 });
  await page.evaluate(() => { window.__silverpine.dismissWarning(); window.__silverpine.start(); });
  await page.waitForTimeout(1200);
  const client = await page.context().newCDPSession(page);

  const joy = await page.locator('#joystick').boundingBox();
  const jx = joy.x + joy.width / 2;
  const jy = joy.y + joy.height / 2;
  console.log('JOYBOX', joy, 'center', jx, jy, 'element', await page.evaluate(([x,y]) => {
    const el = document.elementFromPoint(x,y); return el ? el.id + '|' + el.className : 'none';
  }, [jx, jy]));

  const p0 = await page.evaluate(() => window.__silverpine.player.pos.toArray());
  await client.send('Input.dispatchTouchEvent', { type: 'touchStart', touchPoints: [{ x: jx, y: jy, id: 1 }] });
  for (let i = 1; i <= 6; i++) {
    await client.send('Input.dispatchTouchEvent', { type: 'touchMove', touchPoints: [{ x: jx, y: jy - i * 10, id: 1 }] });
    await page.waitForTimeout(40);
  }
  await page.waitForTimeout(1200);
  console.log('DURING_JOY', await page.evaluate(() => ({ joy: { ...window.__silverpine.state.joy }, pos: window.__silverpine.player.pos.toArray(), knob: document.getElementById('joystickKnob').style.transform })));
  await client.send('Input.dispatchTouchEvent', { type: 'touchEnd', touchPoints: [] });
  await page.waitForTimeout(400);
  const p1 = await page.evaluate(() => window.__silverpine.player.pos.toArray());
  console.log('JOY_MOVE', JSON.stringify({ p0, p1, moved: Math.hypot(p1[0]-p0[0], p1[2]-p0[2]) }));

  // Drag on the canvas to look.
  const yaw0 = await page.evaluate(() => window.__silverpine.player.yaw);
  await client.send('Input.dispatchTouchEvent', { type: 'touchStart', touchPoints: [{ x: 200, y: 300, id: 2 }] });
  for (let i = 1; i <= 6; i++) {
    await client.send('Input.dispatchTouchEvent', { type: 'touchMove', touchPoints: [{ x: 200 - i * 10, y: 300, id: 2 }] });
    await page.waitForTimeout(30);
  }
  await client.send('Input.dispatchTouchEvent', { type: 'touchEnd', touchPoints: [] });
  await page.waitForTimeout(300);
  console.log('LOOK', JSON.stringify({ yaw0, yaw1: await page.evaluate(() => window.__silverpine.player.yaw) }));

  // Tap jump.
  const jb = await page.locator('#jumpButton').boundingBox();
  await client.send('Input.dispatchTouchEvent', { type: 'touchStart', touchPoints: [{ x: jb.x + jb.width/2, y: jb.y + jb.height/2, id: 3 }] });
  await page.waitForTimeout(180);
  const jump = await page.evaluate(() => ({ y: window.__silverpine.player.pos.y, vy: window.__silverpine.player.vy, ground: window.__silverpine.player.onGround }));
  await client.send('Input.dispatchTouchEvent', { type: 'touchEnd', touchPoints: [] });
  console.log('JUMP', JSON.stringify(jump));
  await page.waitForTimeout(700);
  await page.screenshot({ path: 'screenshots/36-mobile-touch.png' });
  console.log('ERRORS', JSON.stringify(errors));
  await browser.close();
})();

